function snapshot(){return JSON.stringify({files:project.files,selectedFileId:project.selectedFileId,selectedFeatureId:project.selectedFeatureId,mergeIds:project.mergeIds})}
function restore(s){VStop(true);const d=JSON.parse(s);project.files=d.files||[];project.selectedFileId=d.selectedFileId||null;project.selectedFeatureId=d.selectedFeatureId||null;project.mergeIds=d.mergeIds||[];renderAll();setDirty(true)}

/* v125: scalable undo history.
   Earlier builds discarded every undo state when the complete project JSON was
   larger than 12 MB. Complex KML/KMZ imports commonly exceed that size because
   each editable feature keeps source, rendered and live geometry. History now
   uses compact feature-scoped entries for in-place edits and a bounded memory
   budget for structural project changes. */
const HISTORY_LIMITS={maxEntries:30,maxBytes:96_000_000,maxSingleBytes:256_000_000};
function historySelectionState(){return {selectedFileId:project.selectedFileId||null,selectedFeatureId:project.selectedFeatureId||null,mergeIds:clone(project.mergeIds||[])};}
function historyEntryBytes(entry){
  if(typeof entry==='string')return entry.length;
  if(!entry||typeof entry!=='object')return 0;
  if(Number.isFinite(entry.bytes))return entry.bytes;
  if(entry.kind==='full')return String(entry.state||'').length;
  if(entry.kind==='features')return (entry.targets||[]).reduce((n,t)=>n+String(t.feature||'').length,0)+512;
  return 0;
}
function trimHistoryStack(stack){
  while(stack.length>HISTORY_LIMITS.maxEntries)stack.shift();
  let total=stack.reduce((n,e)=>n+historyEntryBytes(e),0);
  while(stack.length>1&&total>HISTORY_LIMITS.maxBytes){
    total-=historyEntryBytes(stack.shift());
  }
}
function fullHistoryEntry(){
  const state=snapshot();
  return {kind:'full',state,bytes:state.length};
}
function featureHistoryEntry(featureIds){
  const ids=[...new Set((featureIds||[]).filter(Boolean))];
  const targets=[];
  let bytes=512;
  for(const id of ids){
    const r=ref(id);
    if(!r||!r.file||!r.feature)continue;
    const feature=JSON.stringify(r.feature);
    targets.push({fileId:r.file.id,featureId:r.feature.id,index:r.file.features.indexOf(r.feature),feature});
    bytes+=feature.length;
  }
  if(!targets.length)return null;
  return {kind:'features',targets,...historySelectionState(),bytes};
}
function captureHistoryEntry(featureIds=null){
  const scoped=Array.isArray(featureIds)?featureHistoryEntry(featureIds):null;
  return scoped||fullHistoryEntry();
}
function restoreFeatureHistoryEntry(entry){
  VStop(true);
  for(const target of entry.targets||[]){
    let file=project.files.find(f=>f.id===target.fileId);
    if(!file){
      console.warn('Undo target layer no longer exists:',target.fileId);
      continue;
    }
    const saved=ensureFeatureModel(JSON.parse(target.feature));
    let index=file.features.findIndex(f=>f.id===target.featureId);
    if(index<0){
      index=Math.max(0,Math.min(file.features.length,Number.isInteger(target.index)?target.index:file.features.length));
      file.features.splice(index,0,saved);
    }else{
      file.features[index]=saved;
    }
  }
  project.selectedFileId=entry.selectedFileId||null;
  project.selectedFeatureId=entry.selectedFeatureId||null;
  project.mergeIds=clone(entry.mergeIds||[]);
  renderAll();
  setDirty(true);
}
function restoreHistoryEntry(entry){
  if(typeof entry==='string'){restore(entry);return;}
  if(entry?.kind==='features'){restoreFeatureHistoryEntry(entry);return;}
  if(entry?.kind==='full'){restore(entry.state);return;}
  throw Error('Unsupported undo history entry.');
}
function inverseHistoryEntry(entry){
  if(entry?.kind==='features')return featureHistoryEntry((entry.targets||[]).map(t=>t.featureId));
  return fullHistoryEntry();
}
function pushHistory(featureIds=null){
  try{
    const entry=captureHistoryEntry(featureIds);
    if(entry.kind==='full'&&entry.bytes>HISTORY_LIMITS.maxSingleBytes){
      project.history=[];
      project.future=[];
      updateUndo();
      writeAutosaveNow('very-large-edit-before-change');
      setStatus('This project is too large for a safe in-memory undo snapshot. A recovery autosave was written.','error');
      return false;
    }
    project.history.push(entry);
    trimHistoryStack(project.history);
    project.future=[];
    updateUndo();
    return true;
  }catch(err){
    console.warn('History snapshot skipped:',err);
    project.history=[];
    project.future=[];
    updateUndo();
    return false;
  }
}
function notifyHistoryRestored(direction){
  try{window.dispatchEvent(new CustomEvent('editpolygon:history-restored',{detail:{direction}}));}catch(_){ }
}
function undo(){
  if(imageOverlayById(IMAGE.selectedId)&&IMAGE.history.length){imageUndo();return;}
  if(!project.history.length)return;
  const prev=project.history.pop();
  try{
    const cur=inverseHistoryEntry(prev);
    if(cur){project.future.push(cur);trimHistoryStack(project.future);}
    restoreHistoryEntry(prev);
    updateUndo();
    notifyHistoryRestored('undo');
    setStatus('Undo.');
  }catch(err){
    console.error('Undo failed:',err);
    project.history.push(prev);
    updateUndo();
    setStatus('Undo could not be completed: '+(err.message||err),'error');
  }
}
function redo(){
  if(imageOverlayById(IMAGE.selectedId)&&IMAGE.future.length){imageRedo();return;}
  if(!project.future.length)return;
  const next=project.future.pop();
  try{
    const cur=inverseHistoryEntry(next);
    if(cur){project.history.push(cur);trimHistoryStack(project.history);}
    restoreHistoryEntry(next);
    updateUndo();
    notifyHistoryRestored('redo');
    setStatus('Redo.');
  }catch(err){
    console.error('Redo failed:',err);
    project.future.push(next);
    updateUndo();
    setStatus('Redo could not be completed: '+(err.message||err),'error');
  }
}
function updateUndo(){$('undoBtn').disabled=!(project.history.length||IMAGE.history.length);$('redoBtn').disabled=!(project.future.length||IMAGE.future.length)}

