const featureGroup=L.featureGroup().addTo(map);const geometryPreviewGroup=L.featureGroup().addTo(map);const locationSearchGroup=L.featureGroup().addTo(map);const measurementGroup=L.featureGroup().addTo(map);let drawLayer=null,drawPoints=[];


function parseLatLngSearch(q){
  const s=String(q||'').trim();
  if(!s)return null;
  const m=s.match(/^\s*(-?\d+(?:\.\d+)?)\s*[,;\s]\s*(-?\d+(?:\.\d+)?)\s*$/);
  if(!m)return null;
  let a=Number(m[1]), b=Number(m[2]);
  if(!Number.isFinite(a)||!Number.isFinite(b))return null;
  // Default to lat,lng. If the first value cannot be latitude but second can,
  // treat it as lng,lat.
  let lat=a,lng=b;
  if(Math.abs(a)>90 && Math.abs(b)<=90){lat=b;lng=a;}
  if(Math.abs(lat)>90||Math.abs(lng)>180)return null;
  return {lat,lng,label:`${lat.toFixed(6)}, ${lng.toFixed(6)}`};
}
function setLocationMarker(lat,lng,label='Search result'){
  locationSearchGroup.clearLayers();
  const icon=L.divIcon({className:'location-marker',html:'',iconSize:[18,18],iconAnchor:[9,9]});
  const marker=L.marker([lat,lng],{icon,zIndexOffset:2000}).bindPopup(esc(label));
  marker.addTo(locationSearchGroup);
  marker.openPopup();
  return marker;
}
async function searchLocation(){
  const input=$('locationSearchInput');
  const q=input.value.trim();
  if(!q){setStatus('Enter a place name or lat, lng.','error');return}
  const parsed=parseLatLngSearch(q);
  if(parsed){
    setLocationMarker(parsed.lat,parsed.lng,parsed.label);
    MAP_RUNTIME.setView([parsed.lng,parsed.lat],Math.max(MAP_RUNTIME.getZoom(),14));
    setStatus(`Located ${parsed.label}.`);
    return;
  }
  const oldStatus=$('statusText').textContent;
  try{
    setStatus('Searching location…');
    const params=new URLSearchParams({format:'jsonv2',q,limit:'5',addressdetails:'1'});
    const res=await fetch('https://nominatim.openstreetmap.org/search?'+params.toString(),{
      headers:{'Accept':'application/json'}
    });
    if(!res.ok)throw Error(`Geocoder returned ${res.status}`);
    const rows=await res.json();
    if(!Array.isArray(rows)||!rows.length){
      setStatus(`No location found for "${q}".`,'error');
      return;
    }
    const r=rows[0];
    const lat=Number(r.lat), lng=Number(r.lon);
    if(!Number.isFinite(lat)||!Number.isFinite(lng))throw Error('Invalid geocoder result');
    const label=r.display_name||q;
    setLocationMarker(lat,lng,label);
    if(r.boundingbox&&r.boundingbox.length===4){
      const bb=r.boundingbox.map(Number);
      if(bb.every(Number.isFinite)){
        MAP_RUNTIME.fitExtent([bb[2],bb[0],bb[3],bb[1]],{padding:[30,30],maxZoom:15});
      }else{
        MAP_RUNTIME.setView([lng,lat],13);
      }
    }else{
      MAP_RUNTIME.setView([lng,lat],13);
    }
    setStatus(`Located ${label}.`);
  }catch(err){
    console.error(err);
    setStatus('Location search failed. Check internet access or try lat, lng.','error');
    setTimeout(()=>{if($('statusText').textContent.startsWith('Location search failed'))setStatus(oldStatus||'Ready.')},5000);
  }
}
function clearLocationSearch(){
  locationSearchGroup.clearLayers();
  const input=$('locationSearchInput');
  if(input)input.value='';
  setStatus('Location search cleared.');
}

