  m.querySelector('[data-a="zoomfile"]').onclick=()=>{closeLayerMenu();zoomFile(fileId)};
  m.querySelector('[data-a="removefile"]').onclick=()=>{closeLayerMenu();removeFile(fileId)};
  m.querySelector('[data-a="fileopacity"]').oninput=ev=>setFileOpacity(fileId,ev.target.value);
