function renderEditStackPanel(feature){
  const panel=$('selectedPanel');
  if(!panel||!feature)return;
  ensureFeatureModel(feature);
  const edits=feature.editStack||[];
  const wrap=document.createElement('div');
  wrap.className='edit-stack';
  wrap.innerHTML=`<div class="edit-stack-title"><span>Edit History</span><span class="subtle">${edits.length} edit${edits.length===1?'':'s'}</span></div>`;
  if(!edits.length){
    const empty=document.createElement('div');
    empty.className='edit-empty';
    empty.textContent='No non-destructive edits. Geometry tools will appear here.';
    wrap.appendChild(empty);
  }else{
    edits.forEach((edit,idx)=>{
      const row=document.createElement('div');
      row.className='edit-row'+(edit.enabled===false?' disabled':'');
      row.innerHTML=`<input type="checkbox" ${edit.enabled!==false?'checked':''} data-edit-action="toggle" data-edit-id="${edit.id}">
        <div class="edit-row-main"><div class="edit-row-name">${esc(idx+1+'. '+editLabel(edit))}</div><div class="edit-row-meta">${esc(editSummary(edit))}</div></div>
        <button class="edit-mini" data-edit-action="up" data-edit-id="${edit.id}">↑</button>
        <button class="edit-mini" data-edit-action="down" data-edit-id="${edit.id}">↓</button>
        <button class="edit-mini" data-edit-action="edit" data-edit-id="${edit.id}">Edit</button>
        <button class="edit-mini danger" data-edit-action="delete" data-edit-id="${edit.id}">Delete</button>`;
      wrap.appendChild(row);
    });
  }
  const actions=document.createElement('div');
  actions.className='input-row';
  actions.style.marginTop='8px';
  actions.innerHTML=`<button id="flattenEditsBtn">Flatten edits</button><button id="clearEditsBtn">Clear edits</button>`;
  wrap.appendChild(actions);
  panel.appendChild(wrap);
  wrap.querySelectorAll('[data-edit-action]').forEach(el=>el.addEventListener('click',handleEditStackAction));
  wrap.querySelectorAll('input[data-edit-action]').forEach(el=>el.addEventListener('change',handleEditStackAction));
  const flat=$('flattenEditsBtn'); if(flat)flat.onclick=()=>{pushHistory();flattenEdits(feature);renderAll();setDirty(true);setStatus('Edits flattened into source geometry.');};
  const clear=$('clearEditsBtn'); if(clear)clear.onclick=()=>{if(!confirm('Clear all non-destructive edits for this polygon?'))return;pushHistory();clearEdits(feature);renderAll();setDirty(true);setStatus('Edit stack cleared.');};
}
function editSummary(edit){
  const p=edit.params||{};
  if(edit.type==='simplify')return Number.isFinite(Number(p.toleranceKm))?`Tolerance ${simplifyToleranceLabel(p.toleranceKm)}`:`Legacy tolerance ${p.tolerance}°`;
  if(edit.type==='smooth')return `${p.iterations||1} iteration${Number(p.iterations||1)===1?'':'s'}`;
  if(edit.type==='offset')return `${Number(p.distanceMetres||0)>=0?'Expand':'Inset'} ${Math.abs(Number(p.distanceMetres||0)).toLocaleString()} m`;
  if(edit.type==='truncate')return `${p.decimals??6} decimal place${Number(p.decimals??6)===1?'':'s'}`;
  if(edit.type==='cut'||edit.type==='clip'||edit.type==='erase'||edit.type==='intersect')return 'Uses stored cutter/boundary geometry';
  if(edit.type==='drawHole')return `${(p.ring||[]).length} ring points`;
  if(edit.type==='splitLine')return `${(p.line||[]).length} line points · ${p.widthMetres} m`;
  if(edit.type==='repair')return 'Clean rings / duplicate points';
  if(edit.type==='fillHoles')return 'Remove all inner rings';
  return '';
}
function handleEditStackAction(e){
  const el=e.currentTarget;
  const action=el.dataset.editAction;
  const id=el.dataset.editId;
  const r=ref();
  if(!r)return;
  const stack=r.feature.editStack||[];
  const idx=stack.findIndex(x=>x.id===id);
  if(idx<0)return;
  pushHistory();
  if(action==='toggle'){
    stack[idx].enabled=el.checked;
  }else if(action==='delete'){
    stack.splice(idx,1);
  }else if(action==='up'&&idx>0){
    [stack[idx-1],stack[idx]]=[stack[idx],stack[idx-1]];
  }else if(action==='down'&&idx<stack.length-1){
    [stack[idx+1],stack[idx]]=[stack[idx],stack[idx+1]];
  }else if(action==='edit'){
    editStackParameters(stack[idx]);
  }
  recomputeFeature(r.feature);
  renderAll();
  setDirty(true);
}
function editStackParameters(edit){
  if(edit.type==='simplify'){
    const current=Number.isFinite(Number(edit.params.toleranceKm))?Number(edit.params.toleranceKm):0.01;
    const n=askNumber('Simplify tolerance in kilometres',current);
    if(n!=null&&n>0){edit.params.toleranceKm=n;delete edit.params.tolerance;}
  }else if(edit.type==='smooth'){
    const n=askNumber('Smooth iterations', edit.params.iterations||1);
    if(n!=null&&n>=1)edit.params.iterations=Math.min(3,Math.round(n));
  }else if(edit.type==='splitLine'){
    const n=askNumber('Split line width in metres', edit.params.widthMetres||0.5);
    if(n!=null&&n>0)edit.params.widthMetres=n;
  }else if(edit.type==='offset'){
    const n=askNumber('Offset distance in metres. Use negative values for inset.', edit.params.distanceMetres||1000);
    if(n!=null&&Number.isFinite(n))edit.params.distanceMetres=n;
  }else if(edit.type==='truncate'){
    const n=askNumber('Coordinate decimal places', edit.params.decimals??6);
    if(n!=null&&n>=0)edit.params.decimals=Math.max(0,Math.min(12,Math.round(n)));
  }else{
    alert('This edit has no editable parameters yet.');
  }
}

function setMode(mode){if(MOVE.active&&mode!=='movePolygon')stopPolygonMoveMode(true);if(V.active)VStop(true);if(D.active&&mode!=='draw')DCancel(true);project.mode=mode;if(mode==='select'){setNotice('Select a polygon, then click <strong>Edit polygon</strong>.');setStatus('Select mode.')}else if(mode==='draw'){DStart()}renderAll()}

function maybeAddFinalDoubleClickPoint(e){
  if(!D.active)return;
  const ll=drawOverlayLatLng(e);
  const snap=snappedLatLng(ll,{event:e});
  const c=snap.coord;
  const last=D.points[D.points.length-1];
  if(!last){
    D.points.push(c);
    return;
  }
  const pLast=MAP_RUNTIME.latLngToPixel([last[1],last[0]]);
  const pNow=MAP_RUNTIME.latLngToPixel([c[1],c[0]]);
  // Browsers usually fire a click before dblclick. If that already added this
  // point, this does nothing; otherwise it adds the double-click location.
  if(pLast.distanceTo(pNow)>4)D.points.push(c);
}

