function zoomFile(fid){const file=project.files.find(f=>f.id===fid);if(!file)return;try{MAP_RUNTIME.fitExtent(turf.bbox({type:'FeatureCollection',features:file.features.map(featJSON)}),{padding:[24,24]})}catch{}}
