  if(geometry.type==='MultiPolygon')return `<gml:MultiSurface srsName="urn:ogc:def:crs:OGC::CRS84">${geometry.coordinates.map(poly=>`<gml:surfaceMember>${gmlPolygonXml(poly)}</gml:surfaceMember>`).join('')}</gml:MultiSurface>`;
