function toGml(collection,name){
  return `<?xml version="1.0" encoding="UTF-8"?><gml:FeatureCollection xmlns:gml="http://www.opengis.net/gml" xmlns:ep="https://editpolygon.com/gml"><gml:name>${escXml(name)}</gml:name>${collection.features.map((feature,index)=>`<gml:featureMember><ep:polygon gml:id="feature-${index+1}"><gml:name>${escXml(featureName(feature,`Feature ${index+1}`))}</gml:name><ep:geometry>${geomGml(feature.geometry)}</ep:geometry></ep:polygon></gml:featureMember>`).join('')}</gml:FeatureCollection>`;
}
async function exportData(){
  const scope=$('exportScope').value, format=$('exportFormat').value;
  let collection, name='project';
  if(scope==='selected'){
    const f=selectedFeature();
    if(!f)return alert('Select a feature first');
    collection={type:'FeatureCollection',features:[featJSON(f)]};
    name=basename(f.name);
  }else if(scope==='visible'){
    collection=projectFC({visibleOnly:true});
    name='visible_features';
  }else{
    collection=projectFC();
  }
  if(!collection.features.length)return alert('No features to export');
  const feats=collection.features.map(raw=>{
    const props=raw.properties||{};
    return {
      id: props.id || props.name || uid('export'),
      name: props.name || 'feature',
      properties: props,
      geometry: raw.geometry,
      sourceGeometry: raw.geometry,
      renderedGeometry: raw.geometry,
      editStack: []
    };
  });
  if(format==='geojson'){
    downloadText(name+'.geojson',JSON.stringify(collection,null,2),'application/geo+json;charset=utf-8');
  }else if(format==='kml'){
    downloadText(name+'.kml',toKml(collection,name),'application/vnd.google-earth.kml+xml;charset=utf-8');
  }else if(format==='kmz'){
    const zip=new JSZip();
    zip.file('doc.kml',toKml(collection,name));
    downloadBlob(name+'.kmz',await zip.generateAsync({type:'blob',mimeType:'application/vnd.google-earth.kmz'}));
  }else if(format==='gml'){
    downloadText(name+'.gml',toGml(collection,name),'application/gml+xml;charset=utf-8');
  }else if(format==='csv'){
    downloadText(name+'.csv',featuresToCSV(feats),'text/csv;charset=utf-8');
  }else if(format==='wkt'){
    // Write plain standards-friendly WKT separated by semicolons so it can be re-imported directly.
    const wkt=feats.map(f=>geomToWKT(getDisplayGeometry(f))).join(';\n');
    downloadText(name+'.wkt',wkt,'text/plain;charset=utf-8');
  }else if(format==='topojson'){
    try{
      downloadText(name+'.topojson',featuresToTopoJSON(feats),'application/json;charset=utf-8');
    }catch(err){
      alert('TopoJSON export failed: '+(err.message||err));
    }
  }else if(format==='shp'){
    try{
      await exportShapefileZip(name,collection);
    }catch(err){
      alert('Shapefile export failed: '+(err.message||err));
    }
  }
  setStatus(`Exported ${collection.features.length} feature${collection.features.length===1?'':'s'} as ${format.toUpperCase()}.`);
}

function converterFormatExtension(format){
  return ({geojson:'geojson',kml:'kml',kmz:'kmz',gml:'gml',csv:'csv',wkt:'wkt',topojson:'topojson',shp:'zip'})[format]||format;
}
function converterFormatName(format){
  return ({geojson:'GeoJSON',kml:'KML',kmz:'KMZ',gml:'GML',csv:'CSV',wkt:'WKT',topojson:'TopoJSON',shp:'Shapefile ZIP'})[format]||String(format||'').toUpperCase();
}
function modelFromGeoJSONFeature(raw,i=0){
  const props=raw.properties||{};
  return {
    id:String(props.id||props.feature_id||props.name||uid('convert')),
    name:String(props.name||props.title||props.id||`feature_${i+1}`),
    properties:props,
    geometry:raw.geometry,
    sourceGeometry:raw.geometry,
    renderedGeometry:raw.geometry,
    editStack:[]
  };
}
function featureModelsFromCollection(collection){
  return (collection.features||[]).map((raw,i)=>modelFromGeoJSONFeature(raw,i));
}
function converterCollectionSummary(collection){
  const s=featureCollectionSummary(collection);
  return `${s.features} feature${s.features===1?'':'s'} · ${s.polygons} polygon${s.polygons===1?'':'s'} · ${s.multipolygons} multipolygon${s.multipolygons===1?'':'s'} · ${s.vertices} vertices`;
}
async function downloadCollectionAsFormat(collection,baseName,format){
  const name=basename(baseName||'converted_polygons');
  const feats=featureModelsFromCollection(collection);
  if(format==='geojson'){
    downloadText(name+'.geojson',JSON.stringify(collection,null,2),'application/geo+json;charset=utf-8');
  }else if(format==='kml'){
    downloadText(name+'.kml',toKml(collection,name),'application/vnd.google-earth.kml+xml;charset=utf-8');
  }else if(format==='kmz'){
    const zip=new JSZip();
    zip.file('doc.kml',toKml(collection,name));
    downloadBlob(name+'.kmz',await zip.generateAsync({type:'blob',mimeType:'application/vnd.google-earth.kmz'}));
  }else if(format==='gml'){
    downloadText(name+'.gml',toGml(collection,name),'application/gml+xml;charset=utf-8');
  }else if(format==='csv'){
    downloadText(name+'.csv',featuresToCSV(feats),'text/csv;charset=utf-8');
  }else if(format==='wkt'){
    const wkt=feats.map(f=>geomToWKT(getDisplayGeometry(f))).join(';\n');
    downloadText(name+'.wkt',wkt,'text/plain;charset=utf-8');
  }else if(format==='topojson'){
    downloadText(name+'.topojson',featuresToTopoJSON(feats),'application/json;charset=utf-8');
  }else if(format==='shp'){
    await exportShapefileZip(name,collection);
  }else{
    throw Error('Unsupported output format: '+format);
  }
}
const CONVERTER={items:[],useProject:false};
function openConverterModal(){
  const modal=$('converterModal');
  if(!modal)return;
  modal.classList.add('active');
  renderConverterPanel();
  setTimeout(()=>$('converterFormatSelect')?.focus(),0);
}
function closeConverterModal(){
  $('converterModal')?.classList.remove('active');
}
function clearConverterSources(){
  CONVERTER.items=[];
  CONVERTER.useProject=false;
  const input=$('converterFileInput');
  if(input)input.value='';
  renderConverterPanel();
}
function currentProjectPolygonCollection(){
  const fc=projectFC();
  fc.features=(fc.features||[]).filter(f=>f.geometry&&polygonSupported(f.geometry.type));
  return fc;
}
function converterPreparedCollection(){
  if(CONVERTER.useProject)return currentProjectPolygonCollection();
  const features=[];
  for(const item of CONVERTER.items){
    for(const f of item.features||[])features.push(featJSON(f));
  }
  return {type:'FeatureCollection',features};
}
function renderConverterPanel(){
  const list=$('converterFileList');
  const summary=$('converterSummary');
  const status=$('converterStatus');
  if(!list||!summary)return;
  list.innerHTML='';
  if(status){status.textContent='';status.className='converter-status';}
  if(CONVERTER.useProject){
    const fc=currentProjectPolygonCollection();
    list.innerHTML=`<div class="converter-file-row"><div><strong>Current project polygons</strong><small>${converterCollectionSummary(fc)}</small></div><span class="converter-badge">PROJECT</span></div>`;
    summary.textContent=fc.features.length?`Ready: ${converterCollectionSummary(fc)}.`:'Current project has no polygon features to convert.';
    return;
  }
  if(!CONVERTER.items.length){
    summary.textContent='No source selected.';
    return;
  }
  for(const item of CONVERTER.items){
    const row=document.createElement('div');
    row.className='converter-file-row';
    row.innerHTML=`<div><strong>${esc(item.name)}</strong><small>${item.summary}</small></div><span class="converter-badge">${esc(String(item.sourceFormat||'file').toUpperCase())}</span>`;
    list.appendChild(row);
  }
  const fc=converterPreparedCollection();
  summary.textContent=`Ready to convert ${converterCollectionSummary(fc)}.`;
}
async function prepareConverterFiles(files){
  const selected=Array.from(files||[]);
  if(!selected.length)return;
  CONVERTER.items=[];
  CONVERTER.useProject=false;
  const status=$('converterStatus');
  if(status){status.className='converter-status';status.textContent='Reading files…';}
  const errors=[];
  for(let i=0;i<selected.length;i++){
    const file=selected[i];
    try{
      if(status)status.textContent=`Reading ${file.name} (${i+1} of ${selected.length})…`;
      const imported=await importFile(file,(msg,p)=>{if(status)status.textContent=msg;});
      if(imported&&imported.__pedProject){
        const payload=normaliseSavedProjectPayload(imported.payload);
        const features=[];
        for(const pf of payload.files||[]){
          for(const feat of pf.features||[]){
            const model=ensureFeatureModel(clone(feat));
            if(model.geometry&&polygonSupported(getDisplayGeometry(model).type))features.push(model);
          }
        }
        CONVERTER.items.push({name:file.name,sourceFormat:'project',features,summary:`${features.length} polygon feature${features.length===1?'':'s'} extracted from project file`});
      }else if(imported&&imported.features){
        const features=(imported.features||[]).filter(f=>f.geometry&&polygonSupported(getDisplayGeometry(f).type));
        const fc={type:'FeatureCollection',features:features.map(featJSON)};
        CONVERTER.items.push({name:file.name,sourceFormat:imported.sourceFormat||file.name.split('.').pop().toLowerCase(),features,summary:converterCollectionSummary(fc)});
      }
    }catch(err){
      errors.push(`${file.name}: ${err.message||err}`);
    }
  }
  renderConverterPanel();
  if(status){
    if(errors.length){status.className='converter-status error';status.textContent=errors.join('\n');}
    else{status.className='converter-status ok';status.textContent='Files ready. Choose an output format and convert.';}
  }
}
async function runConverter(){
  const status=$('converterStatus');
  try{
    const format=$('converterFormatSelect')?.value||'geojson';
    const name=($('converterNameInput')?.value||'converted_polygons').trim()||'converted_polygons';
    const collection=converterPreparedCollection();
    if(!collection.features.length)throw Error('No polygon features selected for conversion.');
    if(status){status.className='converter-status';status.textContent=`Converting ${collection.features.length} feature${collection.features.length===1?'':'s'} to ${converterFormatName(format)}…`;}
    await downloadCollectionAsFormat(collection,name,format);
    if(status){status.className='converter-status ok';status.textContent=`Downloaded ${name}.${converterFormatExtension(format)}.`;}
    setStatus(`Converted ${collection.features.length} polygon feature${collection.features.length===1?'':'s'} to ${converterFormatName(format)}.`);
  }catch(err){
    if(status){status.className='converter-status error';status.textContent=err.message||String(err);}
    alert('Conversion failed: '+(err.message||err));
  }
}
function wireConverterControls(){
  const modal=$('converterModal');
  if(!modal)return;
  $('converterOpenBtn')?.addEventListener('click',openConverterModal);
  $('converterCloseBtn')?.addEventListener('click',closeConverterModal);
  $('converterCancelBtn')?.addEventListener('click',closeConverterModal);
  $('converterChooseBtn')?.addEventListener('click',()=>$('converterFileInput')?.click());
  $('converterClearBtn')?.addEventListener('click',clearConverterSources);
  $('converterUseProjectBtn')?.addEventListener('click',()=>{CONVERTER.items=[];CONVERTER.useProject=true;renderConverterPanel();});
  $('converterRunBtn')?.addEventListener('click',runConverter);
  $('converterRunFooterBtn')?.addEventListener('click',runConverter);
  $('converterFileInput')?.addEventListener('change',e=>{prepareConverterFiles(e.target.files);});
  modal.addEventListener('click',e=>{if(e.target===modal)closeConverterModal();});
  const dz=$('converterDropzone');
  if(dz){
    dz.addEventListener('click',()=>$('converterFileInput')?.click());
    ['dragenter','dragover'].forEach(type=>dz.addEventListener(type,e=>{e.preventDefault();e.stopPropagation();dz.classList.add('dragover');}));
    ['dragleave','drop'].forEach(type=>dz.addEventListener(type,e=>{e.preventDefault();e.stopPropagation();dz.classList.remove('dragover');}));
    dz.addEventListener('drop',e=>prepareConverterFiles(e.dataTransfer?.files));
  }
}


const VALIDATOR={items:[],useProject:false,original:null,fixed:null,issues:[],lastReport:null};
function validatorFormatName(format){return converterFormatName(format);}
function validatorFormatExtension(format){return converterFormatExtension(format);}
function validatorCoordValid(c){return Array.isArray(c)&&Number.isFinite(Number(c[0]))&&Number.isFinite(Number(c[1]));}
function validatorCoordSame(a,b){return validatorCoordValid(a)&&validatorCoordValid(b)&&Number(a[0])===Number(b[0])&&Number(a[1])===Number(b[1]);}
function validatorRound(n){return Math.round(Number(n)*1e10)/1e10;}
function validatorCoordKey(c){return `${validatorRound(c[0])},${validatorRound(c[1])}`;}
function validatorRingKey(r){
  const pts=(r||[]).filter(validatorCoordValid);
  const body=pts.length>1&&validatorCoordSame(pts[0],pts[pts.length-1])?pts.slice(0,-1):pts;
  return body.map(validatorCoordKey).sort().join(';');
}
function validatorRingArea(r){
  const pts=(r||[]).filter(validatorCoordValid);
  if(pts.length<3)return 0;
  let area=0;
  for(let i=0;i<pts.length-1;i++)area+=Number(pts[i][0])*Number(pts[i+1][1])-Number(pts[i+1][0])*Number(pts[i][1]);
  if(!validatorCoordSame(pts[0],pts[pts.length-1])){
    const a=pts[pts.length-1],b=pts[0];
    area+=Number(a[0])*Number(b[1])-Number(b[0])*Number(a[1]);
  }
  return area/2;
}
function validatorOrientation(a,b,c){
  const v=(Number(b[1])-Number(a[1]))*(Number(c[0])-Number(b[0]))-(Number(b[0])-Number(a[0]))*(Number(c[1])-Number(b[1]));
  if(Math.abs(v)<1e-12)return 0;
  return v>0?1:2;
}
function validatorOnSegment(a,b,c){
  return Math.min(Number(a[0]),Number(c[0]))-1e-12<=Number(b[0])&&Number(b[0])<=Math.max(Number(a[0]),Number(c[0]))+1e-12&&
         Math.min(Number(a[1]),Number(c[1]))-1e-12<=Number(b[1])&&Number(b[1])<=Math.max(Number(a[1]),Number(c[1]))+1e-12;
}
function validatorSegmentsIntersect(p1,q1,p2,q2){
  const o1=validatorOrientation(p1,q1,p2),o2=validatorOrientation(p1,q1,q2),o3=validatorOrientation(p2,q2,p1),o4=validatorOrientation(p2,q2,q1);
  if(o1!==o2&&o3!==o4)return true;
  if(o1===0&&validatorOnSegment(p1,p2,q1))return true;
  if(o2===0&&validatorOnSegment(p1,q2,q1))return true;
  if(o3===0&&validatorOnSegment(p2,p1,q2))return true;
  if(o4===0&&validatorOnSegment(p2,q1,q2))return true;
  return false;
}
function validatorSelfIntersections(r){
  const pts=(r||[]).filter(validatorCoordValid);
  const ring=pts.length>1&&validatorCoordSame(pts[0],pts[pts.length-1])?pts:pts.concat([pts[0]]);
  const n=ring.length-1;
  const hits=[];
  if(n>900)return [{skipped:true,count:n}];
  for(let i=0;i<n;i++){
    for(let j=i+1;j<n;j++){
      if(Math.abs(i-j)<=1)continue;
      if(i===0&&j===n-1)continue;
      if(validatorSegmentsIntersect(ring[i],ring[i+1],ring[j],ring[j+1]))hits.push([i,j]);
      if(hits.length>=25)return hits;
    }
  }
  return hits;
}
function validatorFeatureCollectionBBox(fc){
  let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity,count=0;
  function visitCoords(coords){
    if(!Array.isArray(coords))return;
    if(coords.length>=2&&Number.isFinite(Number(coords[0]))&&Number.isFinite(Number(coords[1]))){
      const x=Number(coords[0]),y=Number(coords[1]);
      minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y);count++;
      return;
    }
    coords.forEach(visitCoords);
  }
  for(const f of fc.features||[])if(f.geometry)visitCoords(f.geometry.coordinates);
  return count?{minX,minY,maxX,maxY,count}:null;
}
function validatorFeatureBBoxAndArea(feature){
  const g=feature&&feature.geometry;
  let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity,count=0,area=0;
  const visitPoint=(c)=>{
    if(!validatorCoordValid(c))return;
    const x=Number(c[0]),y=Number(c[1]);
    minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y);count++;
  };
  const visitRing=(ring,outer)=>{
    const pts=(ring||[]).filter(validatorCoordValid);
    pts.forEach(visitPoint);
    const a=Math.abs(validatorRingArea(pts));
    area+=outer?a:-a;
  };
  if(g&&g.type==='Polygon'){
    (g.coordinates||[]).forEach((ring,ri)=>visitRing(ring,ri===0));
  }else if(g&&g.type==='MultiPolygon'){
    (g.coordinates||[]).forEach(poly=>(poly||[]).forEach((ring,ri)=>visitRing(ring,ri===0)));
  }
  return count?{minX,minY,maxX,maxY,count,area:Math.abs(area)}:null;
}
function validatorBBoxArea(b){
  if(!b)return 0;
  return Math.max(0,Number(b.maxX)-Number(b.minX))*Math.max(0,Number(b.maxY)-Number(b.minY));
}
function validatorBBoxOverlapRatio(a,b){
  if(!a||!b)return 0;
  const ix=Math.max(0,Math.min(a.maxX,b.maxX)-Math.max(a.minX,b.minX));
  const iy=Math.max(0,Math.min(a.maxY,b.maxY)-Math.max(a.minY,b.minY));
  const inter=ix*iy;
  const denom=Math.min(validatorBBoxArea(a),validatorBBoxArea(b));
  return denom>0?inter/denom:0;
}
function validatorFeatureGeometryKey(feature){
  const g=feature&&feature.geometry;
  if(!g)return '';
  const roundCoord=(c)=>validatorCoordValid(c)?[validatorRound(c[0]),validatorRound(c[1])]:c;
  const roundNested=(v)=>Array.isArray(v)?v.map(x=>Array.isArray(x)?roundNested(x):x):v;
  return JSON.stringify({type:g.type,coordinates:roundNested(g.coordinates)});
}
function validatorFeatureProfile(feature,index){
  const name=String((feature&&feature.properties&&(feature.properties.name||feature.properties.Name||feature.properties.NAME))||`Feature ${index+1}`).trim();
  const bbox=validatorFeatureBBoxAndArea(feature);
  return {feature,index,name,normName:name.toLowerCase(),bbox,area:bbox?bbox.area:0,key:validatorFeatureGeometryKey(feature)};
}
function validatorLikelyDuplicateProfile(a,b){
  if(!a||!b||!a.bbox||!b.bbox)return false;
  if(!a.normName||a.normName!==b.normName)return false;
  const overlap=validatorBBoxOverlapRatio(a.bbox,b.bbox);
  const minArea=Math.min(a.area||0,b.area||0),maxArea=Math.max(a.area||0,b.area||0);
  const areaRatio=maxArea>0?minArea/maxArea:0;
  return overlap>=0.85&&areaRatio>=0.75;
}
function validatorDropDuplicateFeatures(features){
  const kept=[];
  const profiles=[];
  for(const feat of features||[]){
    const prof=validatorFeatureProfile(feat,kept.length);
    let dup=-1;
    for(let i=0;i<profiles.length;i++){
      if((prof.key&&profiles[i].key===prof.key)||validatorLikelyDuplicateProfile(prof,profiles[i])){dup=i;break;}
    }
    if(dup<0){
      kept.push(feat);profiles.push(validatorFeatureProfile(feat,kept.length-1));
    }else if((prof.area||0)>(profiles[dup].area||0)){
      kept[dup]=feat;profiles[dup]=validatorFeatureProfile(feat,dup);
    }
  }
  return kept;
}
function validatorPointInShell(pt,shell){
  if(!validatorCoordValid(pt)||!Array.isArray(shell)||shell.length<4)return false;
  try{
    if(window.turf&&turf.booleanPointInPolygon)return turf.booleanPointInPolygon(turf.point(pt),turf.polygon([shell]));
  }catch(e){}
  let inside=false;
  for(let i=0,j=shell.length-1;i<shell.length;j=i++){
    const xi=Number(shell[i][0]), yi=Number(shell[i][1]), xj=Number(shell[j][0]), yj=Number(shell[j][1]);
    const intersect=((yi>pt[1])!==(yj>pt[1]))&&(pt[0]<(xj-xi)*(pt[1]-yi)/(yj-yi+0)+xi);
    if(intersect)inside=!inside;
  }
  return inside;
}
function validateCollectionGeometry(collection){
  const fc=ensureFC(collection);
  const issues=[];
  const add=(severity,code,message,path,fix)=>issues.push({severity,code,message,path:path||'',fix:fix||''});
  let ringTotal=0, invalidCoordTotal=0;
  const featureProfiles=[];
  for(const [fi,f] of (fc.features||[]).entries()){
    const geom=f.geometry;
    const fname=featureName(f,`Feature ${fi+1}`);
    const rawIssues=Array.isArray(f.properties&&f.properties.__validatorRawIssues)?f.properties.__validatorRawIssues:[];
    rawIssues.forEach(ri=>add(ri.severity||'error',ri.code||'SOURCE_GEOMETRY_ISSUE',ri.message||'Source file geometry issue detected.',`${fname}${ri.path?' / '+ri.path:''}`,ri.fix||''));
    if(!geom){add('error','EMPTY_GEOMETRY','Feature has no geometry.',fname,'Remove empty feature');continue;}
    if(!polygonSupported(geom.type)){add('error','UNSUPPORTED_GEOMETRY',`Unsupported geometry type ${geom.type}.`,fname,'Use polygon-only geometry');continue;}
    featureProfiles.push(validatorFeatureProfile(f,fi));
    const polygons=geom.type==='Polygon'?[geom.coordinates||[]]:(geom.coordinates||[]);
    polygons.forEach((poly,pi)=>{
      const polyPath=`${fname} / polygon ${pi+1}`;
      if(!Array.isArray(poly)||!poly.length){add('error','EMPTY_POLYGON','Polygon has no rings.',polyPath,'Remove empty polygon');return;}
      const ringKeys=new Set();
      const shell=poly[0];
      poly.forEach((ring,ri)=>{
        ringTotal++;
        const role=ri===0?'outer ring':`hole ${ri}`;
        const path=`${polyPath} / ${role}`;
        if(!Array.isArray(ring)){add('error','BAD_RING','Ring is not an array of coordinates.',path,'Remove invalid ring');return;}
        const bad=ring.filter(c=>!validatorCoordValid(c)).length;
        if(bad){invalidCoordTotal+=bad;add('error','INVALID_COORDINATE',`${bad} coordinate${bad===1?' is':'s are'} not numeric.`,path,'Fix source coordinates');}
        const valid=ring.filter(validatorCoordValid);
        if(valid.length<4)add('error','TOO_FEW_VERTICES','Ring has too few coordinates to form a polygon.',path,'Drop the ring or add vertices');
        if(valid.length&& !validatorCoordSame(valid[0],valid[valid.length-1]))add('error','UNCLOSED_RING','Ring is not closed.',path,'Close rings');
        let dupes=0;
        for(let i=1;i<valid.length;i++)if(validatorCoordSame(valid[i-1],valid[i]))dupes++;
        if(dupes)add('warning','CONSECUTIVE_DUPLICATES',`${dupes} consecutive duplicate vertex${dupes===1?'':' vertices'} found.`,path,'Remove consecutive duplicates');
        const unique=new Set(valid.map(validatorCoordKey));
        if(unique.size<3)add('error','TOO_FEW_UNIQUE_VERTICES','Ring has fewer than 3 unique vertices.',path,'Drop or redraw ring');
        const outRange=valid.filter(c=>Number(c[0])<-180||Number(c[0])>180||Number(c[1])<-90||Number(c[1])>90).length;
        if(outRange)add('warning','COORDINATE_RANGE',`${outRange} coordinate${outRange===1?' is':'s are'} outside WGS84 lon/lat range.`,path,'Check projection / CRS');
        const area=validatorRingArea(valid);
        if(Math.abs(area)<1e-14)add('error','ZERO_AREA_RING','Ring has zero or near-zero area.',path,'Drop zero-area ring');
        else if(ri===0&&area<0)add('warning','WINDING','Outer ring is clockwise; GeoJSON/RFC 7946 expects counter-clockwise.',path,'Enforce winding');
        else if(ri>0&&area>0)add('warning','WINDING','Hole ring is counter-clockwise; GeoJSON/RFC 7946 expects clockwise.',path,'Enforce winding');
        const key=validatorRingKey(valid);
        if(key&&ringKeys.has(key))add('warning','DUPLICATE_RING','Duplicate ring found in this polygon.',path,'Drop duplicate rings');
        else if(key)ringKeys.add(key);
        const self=validatorSelfIntersections(valid);
        if(self.length){
          if(self[0]&&self[0].skipped)add('info','SELF_INTERSECTION_SKIPPED',`Self-intersection scan skipped for large ring (${self[0].count} segments).`,path,'Use desktop GIS or simplify first');
          else add('error','SELF_INTERSECTION',`${self.length} self-intersection${self.length===1?'':'s'} detected.`,path,'Attempt self-intersection repair or redraw');
        }
        if(ri>0&&validatorCoordValid(valid[0])&&Array.isArray(shell)&&shell.length>=4&&!validatorPointInShell(valid[0],shell)){
          add('error','HOLE_OUTSIDE_SHELL','Hole appears to be outside the polygon outer ring.',path,'Drop invalid holes or redraw');
        }
      });
    });
  }
  if(featureProfiles.length>500){
    add('info','DUPLICATE_FEATURE_SCAN_SKIPPED',`Duplicate feature scan skipped for ${featureProfiles.length} features.`,'collection','Validate smaller batches for duplicate-feature checks');
  }else{
    const seenKeys=new Map();
    featureProfiles.forEach((prof)=>{
      if(prof.key&&seenKeys.has(prof.key)){
        const other=seenKeys.get(prof.key);
        add('warning','DUPLICATE_FEATURE',`Feature appears to have exactly the same polygon geometry as ${other.name}.`,prof.name,'Drop duplicate polygon features');
      }else if(prof.key){
        seenKeys.set(prof.key,prof);
      }
    });
    for(let i=0;i<featureProfiles.length;i++){
      for(let j=i+1;j<featureProfiles.length;j++){
        const a=featureProfiles[i],b=featureProfiles[j];
        if(a.key&&b.key&&a.key===b.key)continue;
        if(validatorLikelyDuplicateProfile(a,b)){
          add('warning','POSSIBLE_DUPLICATE_FEATURE',`Feature has the same name and substantially overlapping bounds/area as ${a.name}; it may be a broken or duplicate copy.`,b.name,'Keep the intended feature only or enable duplicate feature removal');
        }
      }
    }
  }
  const summary=featureCollectionSummary(fc);
  const bbox=validatorFeatureCollectionBBox(fc);
  return {issues,summary,bbox,ringTotal,invalidCoordTotal};
}
function validatorRemoveConsecutiveDupes(r){
  const out=[];
  for(const c of r||[]){
    if(!validatorCoordValid(c))continue;
    const p=[Number(c[0]),Number(c[1])];
    if(!out.length||!validatorCoordSame(out[out.length-1],p))out.push(p);
  }
  return out;
}
function validatorFixPolygonRings(rings,opts){
  if(!Array.isArray(rings)||!rings.length)return null;
  let fixed=[];
  const seen=new Set();
  const originalShell=Array.isArray(rings[0])?rings[0]:[];
  rings.forEach((ring,ri)=>{
    let pts=opts.removeDupes?validatorRemoveConsecutiveDupes(ring):(ring||[]).filter(validatorCoordValid).map(c=>[Number(c[0]),Number(c[1])]);
    if(opts.closeRings&&pts.length){ if(!validatorCoordSame(pts[0],pts[pts.length-1]))pts.push([...pts[0]]); else pts[pts.length-1]=[...pts[0]]; }
    if(pts.length&&validatorCoordSame(pts[0],pts[pts.length-1])){
      // Remove repeated copies of the closing coordinate before the final close.
      const body=[];
      for(let i=0;i<pts.length-1;i++){
        if(i>0&&validatorCoordSame(pts[i],pts[0]))continue;
        body.push(pts[i]);
      }
      pts=body.concat([[...body[0]]]);
    }
    if(pts.length<4)return;
    const area=validatorRingArea(pts);
    if(opts.dropZeroArea&&Math.abs(area)<1e-14)return;
    if(ri>0&&opts.dropInvalidHoles&&pts[0]&&originalShell&&originalShell.length>=4&&!validatorPointInShell(pts[0],originalShell))return;
    if(opts.enforceWinding){
      const a=validatorRingArea(pts);
      const shouldReverse=(ri===0&&a<0)||(ri>0&&a>0);
      if(shouldReverse){
        const closedRing=validatorCoordSame(pts[0],pts[pts.length-1]);
        let body=closedRing?pts.slice(0,-1):pts.slice();
        body.reverse();
        pts=body;
        if(opts.closeRings&&pts.length)pts.push([...pts[0]]);
      }
    }
    const key=validatorRingKey(pts);
    if(opts.dropDuplicateRings&&key&&seen.has(key))return;
    if(key)seen.add(key);
    fixed.push(pts);
  });
  if(!fixed.length)return null;
  if(!fixed[0]||fixed[0].length<4)return null;
  return fixed;
}
function repairCollectionGeometry(collection,opts){
  const fc=ensureFC(collection);
  const out=[];
  for(const [fi,f] of (fc.features||[]).entries()){
    if(!f.geometry||!polygonSupported(f.geometry.type))continue;
    const props=clone(f.properties||{});
    let geom=null;
    if(f.geometry.type==='Polygon'){
      const rings=validatorFixPolygonRings(f.geometry.coordinates,opts);
      if(rings)geom={type:'Polygon',coordinates:rings};
    }else if(f.geometry.type==='MultiPolygon'){
      const polys=[];
      for(const poly of f.geometry.coordinates||[]){
        const rings=validatorFixPolygonRings(poly,opts);
        if(rings)polys.push(rings);
      }
      if(polys.length)geom={type:'MultiPolygon',coordinates:polys};
    }
    if(!geom)continue;
    let base={type:'Feature',properties:props,geometry:geom};
    if(opts.repairSelfIntersections&&window.turf&&typeof turf.unkinkPolygon==='function'){
      try{
        const unk=ensureFC(turf.unkinkPolygon(base));
        for(const u of unk.features||[]){
          if(u.geometry&&polygonSupported(u.geometry.type))out.push({type:'Feature',properties:{...props,...(u.properties||{})},geometry:u.geometry});
        }
        continue;
      }catch(err){
        base.properties={...props,validator_repair_note:'Self-intersection repair failed: '+(err.message||err)};
      }
    }
    out.push(base);
  }
  const features=opts.dropDuplicateFeatures?validatorDropDuplicateFeatures(out):out;
  return {type:'FeatureCollection',features};
}
function validatorCurrentOptions(){
  const opts={};
  document.querySelectorAll('[data-validator-fix]').forEach(cb=>opts[cb.dataset.validatorFix]=!!cb.checked);
  return opts;
}
function validatorSetOptions(mode){
  const recommended=new Set(['removeDupes','enforceWinding']);
  document.querySelectorAll('[data-validator-fix]').forEach(cb=>{
    cb.checked=mode==='all'||(mode==='recommended'&&recommended.has(cb.dataset.validatorFix));
    if(mode==='none')cb.checked=false;
  });
}
function validatorPreparedCollection(){
  if(VALIDATOR.useProject)return currentProjectPolygonCollection();
  const features=[];
  for(const item of VALIDATOR.items)for(const f of item.features||[])features.push(featJSON(f));
  return {type:'FeatureCollection',features};
}
function renderValidatorPanel(){
  const list=$('validatorFileList'), summary=$('validatorSummary'), issuesEl=$('validatorIssueList'), overview=$('validatorOverview'), status=$('validatorStatus');
  if(!list||!summary||!issuesEl||!overview)return;
  list.innerHTML='';
  if(status&&!VALIDATOR.items.length&&!VALIDATOR.useProject){status.textContent='';status.className='validator-status';}
  let fc=validatorPreparedCollection();
  VALIDATOR.original=fc;
  const report=fc.features.length?validateCollectionGeometry(fc):null;
  VALIDATOR.lastReport=report;
  VALIDATOR.issues=report?report.issues:[];
  if(VALIDATOR.useProject){
    list.innerHTML=`<div class="validator-file-row"><div><strong>Current project polygons</strong><small>${converterCollectionSummary(fc)}</small></div><span class="validator-badge">PROJECT</span></div>`;
  }else if(VALIDATOR.items.length){
    for(const item of VALIDATOR.items){
      const row=document.createElement('div');
      row.className='validator-file-row';
      row.innerHTML=`<div><strong>${esc(item.name)}</strong><small>${esc(item.summary)}</small></div><span class="validator-badge">${esc(String(item.sourceFormat||'file').toUpperCase())}</span>`;
      list.appendChild(row);
    }
  }
  if(!fc.features.length){
    summary.textContent='No source selected.';
    overview.innerHTML='<span class="validator-chip">No source</span>';
    issuesEl.innerHTML='<div class="coord-help" style="margin:auto;text-align:center">Upload a file or use current project polygons to see issues.</div>';
    $('validatorOutputText').value='';
    return;
  }
  const errors=VALIDATOR.issues.filter(i=>i.severity==='error').length;
  const warnings=VALIDATOR.issues.filter(i=>i.severity==='warning').length;
  const infos=VALIDATOR.issues.filter(i=>i.severity==='info').length;
  const bbox=report.bbox?`${fmt(report.bbox.minX,5)}, ${fmt(report.bbox.minY,5)} → ${fmt(report.bbox.maxX,5)}, ${fmt(report.bbox.maxY,5)}`:'—';
  overview.innerHTML=`<span class="validator-chip ok">Features ${report.summary.features}</span><span class="validator-chip">Polygons ${report.summary.polygons}</span><span class="validator-chip">Multipolygons ${report.summary.multipolygons}</span><span class="validator-chip">Vertices ${report.summary.vertices}</span><span class="validator-chip ${errors?'error':'ok'}">Errors ${errors}</span><span class="validator-chip ${warnings?'warning':'ok'}">Warnings ${warnings}</span><span class="validator-chip">Info ${infos}</span>`;
  summary.textContent=`BBOX: ${bbox}`;
  if(!VALIDATOR.issues.length){
    issuesEl.innerHTML='<div class="validator-issue info"><strong>No issues found</strong><div>This polygon collection appears structurally valid for the checks available here.</div></div>';
  }else{
    issuesEl.innerHTML='';
    for(const issue of VALIDATOR.issues.slice(0,120)){
      const el=document.createElement('div');
      el.className=`validator-issue ${issue.severity||'info'}`;
      el.innerHTML=`<strong>${esc(issue.code)} · ${esc(issue.severity||'info')}</strong><div>${esc(issue.message)}</div>${issue.path?`<small>${esc(issue.path)}</small>`:''}${issue.fix?`<small>Fix: ${esc(issue.fix)}</small>`:''}`;
      issuesEl.appendChild(el);
    }
    if(VALIDATOR.issues.length>120){
      const more=document.createElement('div');more.className='validator-issue info';more.innerHTML=`<strong>More issues hidden</strong><div>${VALIDATOR.issues.length-120} additional issue${VALIDATOR.issues.length-120===1?'':'s'} not shown.</div>`;issuesEl.appendChild(more);
    }
  }
}
async function prepareValidatorFiles(files){
  const selected=Array.from(files||[]);
  if(!selected.length)return;
  VALIDATOR.items=[];VALIDATOR.useProject=false;VALIDATOR.fixed=null;
  const status=$('validatorStatus');
  if(status){status.className='validator-status';status.textContent='Reading files…';}
  const errors=[];
  for(let i=0;i<selected.length;i++){
    const file=selected[i];
    try{
      if(status)status.textContent=`Reading ${file.name} (${i+1} of ${selected.length})…`;
      const imported=await importFile(file,(msg)=>{if(status)status.textContent=msg;});
      if(imported&&imported.__pedProject){
        const payload=normaliseSavedProjectPayload(imported.payload);
        const features=[];
        for(const pf of payload.files||[]){
          for(const feat of pf.features||[]){
            const model=ensureFeatureModel(clone(feat));
            if(model.geometry&&polygonSupported(getDisplayGeometry(model).type))features.push(model);
          }
        }
        VALIDATOR.items.push({name:file.name,sourceFormat:'project',features,summary:`${features.length} polygon feature${features.length===1?'':'s'} extracted from project file`});
      }else if(imported&&imported.features){
        const features=(imported.features||[]).filter(f=>f.geometry&&polygonSupported(getDisplayGeometry(f).type));
        const fc={type:'FeatureCollection',features:features.map(featJSON)};
        VALIDATOR.items.push({name:file.name,sourceFormat:imported.sourceFormat||file.name.split('.').pop().toLowerCase(),features,summary:converterCollectionSummary(fc)});
      }
    }catch(err){errors.push(`${file.name}: ${err.message||err}`);}
  }
  renderValidatorPanel();
  if(status){
    if(errors.length){status.className='validator-status error';status.textContent=errors.join('\n');}
    else{const count=VALIDATOR.issues.length;status.className=count?'validator-status warn':'validator-status ok';status.textContent=count?`Validation complete: ${count} issue${count===1?'':'s'} found.`:'Validation complete: no issues found.';}
  }
}
function openValidatorModal(){
  const modal=$('validatorModal');
  if(!modal)return;
  modal.classList.add('active');
  renderValidatorPanel();
  setTimeout(()=>$('validatorChooseBtn')?.focus(),0);
}
function closeValidatorModal(){ $('validatorModal')?.classList.remove('active'); }
function clearValidatorSources(){
  VALIDATOR.items=[];VALIDATOR.useProject=false;VALIDATOR.fixed=null;VALIDATOR.original=null;VALIDATOR.issues=[];
  const input=$('validatorFileInput');if(input)input.value='';
  renderValidatorPanel();
  const status=$('validatorStatus');if(status){status.className='validator-status';status.textContent='';}
}
function applyValidatorFixes(){
  const status=$('validatorStatus');
  try{
    const source=validatorPreparedCollection();
    if(!source.features.length)throw Error('No polygon features selected for validation.');
    const fixed=repairCollectionGeometry(source,validatorCurrentOptions());
    VALIDATOR.fixed=fixed;
    const before=validateCollectionGeometry(source);
    const after=validateCollectionGeometry(fixed);
    const text=JSON.stringify(fixed,null,2);
    $('validatorOutputText').value=text;
    $('validatorOutputLabel').textContent=`Fixed GeoJSON preview · ${fixed.features.length} feature${fixed.features.length===1?'':'s'}`;
    renderValidatorPanel();
    if(status){
      status.className=after.issues.some(i=>i.severity==='error')?'validator-status warn':'validator-status ok';
      status.textContent=`Applied fixes. Issues before: ${before.issues.length}. Issues after: ${after.issues.length}. Review output before importing if advanced fixes were used.`;
    }
  }catch(err){
    if(status){status.className='validator-status error';status.textContent=err.message||String(err);}else alert(err.message||err);
  }
}
async function downloadValidatorFixed(){
  const status=$('validatorStatus');
  try{
    if(!VALIDATOR.fixed)applyValidatorFixes();
    const fixed=VALIDATOR.fixed;
    if(!fixed||!fixed.features.length)throw Error('No fixed polygon features to download.');
    const format=$('validatorFormatSelect')?.value||'geojson';
    const name=($('validatorNameInput')?.value||'polygons_fixed').trim()||'polygons_fixed';
    if(status){status.className='validator-status';status.textContent=`Exporting fixed result as ${validatorFormatName(format)}…`;}
    await downloadCollectionAsFormat(fixed,name,format);
    if(status){status.className='validator-status ok';status.textContent=`Downloaded ${name}.${validatorFormatExtension(format)}.`;}
    setStatus(`Downloaded validated polygon file as ${validatorFormatName(format)}.`);
  }catch(err){
    if(status){status.className='validator-status error';status.textContent=err.message||String(err);}alert('Validator export failed: '+(err.message||err));
  }
}
function validatorGeometryImportKey(geom){
  if(!geom||!polygonSupported(geom.type))return '';
  function roundCoord(c){return [validatorRound(c?.[0]),validatorRound(c?.[1])];}
  function normRing(r){return (r||[]).filter(validatorCoordValid).map(roundCoord);}
  if(geom.type==='Polygon')return JSON.stringify({type:'Polygon',coordinates:(geom.coordinates||[]).map(normRing)});
  if(geom.type==='MultiPolygon')return JSON.stringify({type:'MultiPolygon',coordinates:(geom.coordinates||[]).map(poly=>(poly||[]).map(normRing))});
  return '';
}
function validatorDeduplicateCollection(collection){
  const fc=ensureFC(collection);
  const seen=new Set();
  const features=[];
  for(const f of fc.features||[]){
    const key=validatorGeometryImportKey(f.geometry);
    if(key&&seen.has(key))continue;
    if(key)seen.add(key);
    features.push(f);
  }
  return {type:'FeatureCollection',features};
}
function validatorRemoveExistingPolygonDuplicates(keys){
  if(!keys||!keys.size)return 0;
  let removed=0;
  project.files=(project.files||[]).map(file=>{
    const kept=[];
    for(const feat of file.features||[]){
      const geom=getDisplayGeometry(feat);
      const key=geom&&polygonSupported(geom.type)?validatorGeometryImportKey(geom):'';
      if(key&&keys.has(key)){removed++;continue;}
      kept.push(feat);
    }
    return {...file,features:kept};
  }).filter(file=>(file.features||[]).length);
  return removed;
}
function validatorReplaceCurrentProjectPolygons(models,color){
  let removed=0;
  const remaining=[];
  for(const file of project.files||[]){
    const kept=[];
    for(const feat of file.features||[]){
      const geom=getDisplayGeometry(feat);
      if(geom&&polygonSupported(geom.type)){removed++;continue;}
      kept.push(feat);
    }
    if(kept.length)remaining.push({...file,features:kept});
  }
  project.files=remaining;
  project.files.push({id:uid('file'),name:'Validated fixed result',sourceFormat:'validator',visible:true,color,features:models});
  return removed;
}
function importValidatorFixed(){
  try{
    if(!VALIDATOR.fixed)applyValidatorFixes();
    const fixed=validatorDeduplicateCollection(VALIDATOR.fixed);
    if(!fixed||!fixed.features.length)throw Error('No fixed polygon features to import.');
    const color=COLORS[project.files.length%COLORS.length];
    const models=[];
    fixed.features.forEach((f,i)=>{const model=normalize(f,featureName(f,`Fixed polygon ${i+1}`));if(model&&model.geometry&&polygonSupported(getDisplayGeometry(model).type)){applyColor(model,color);models.push(model);}});
    if(!models.length)throw Error('Fixed result has no polygon features to import.');
    pushHistory();
    let message='';
    if(VALIDATOR.useProject){
      const removed=validatorReplaceCurrentProjectPolygons(models,color);
      message=`Replaced ${removed} existing project polygon feature${removed===1?'':'s'} with ${models.length} validated polygon feature${models.length===1?'':'s'}.`;
    }else{
      const incomingKeys=new Set(models.map(m=>validatorGeometryImportKey(getDisplayGeometry(m))).filter(Boolean));
      const removed=validatorRemoveExistingPolygonDuplicates(incomingKeys);
      project.files.push({id:uid('file'),name:'Validated fixed result',sourceFormat:'validator',visible:true,color,features:models});
      message=`Imported ${models.length} fixed polygon feature${models.length===1?'':'s'} into the project${removed?` and removed ${removed} exact existing duplicate${removed===1?'':'s'}`:''}.`;
    }
    renderAll();fitAll();setDirty(true);closeValidatorModal();
    setStatus(message);
  }catch(err){alert('Import fixed result failed: '+(err.message||err));}
}
function wireValidatorControls(){
  const modal=$('validatorModal');
  if(!modal)return;
  $('validatorOpenBtn')?.addEventListener('click',openValidatorModal);
  $('validatorCloseBtn')?.addEventListener('click',closeValidatorModal);
  $('validatorCancelBtn')?.addEventListener('click',closeValidatorModal);
  $('validatorChooseBtn')?.addEventListener('click',()=>$('validatorFileInput')?.click());
  $('validatorClearBtn')?.addEventListener('click',clearValidatorSources);
  $('validatorUseProjectBtn')?.addEventListener('click',()=>{VALIDATOR.items=[];VALIDATOR.useProject=true;VALIDATOR.fixed=null;renderValidatorPanel();const st=$('validatorStatus');if(st){st.className=VALIDATOR.issues.length?'validator-status warn':'validator-status ok';st.textContent=VALIDATOR.issues.length?`Validation complete: ${VALIDATOR.issues.length} issue${VALIDATOR.issues.length===1?'':'s'} found.`:'Validation complete: no issues found.';}});
  $('validatorRecommendedBtn')?.addEventListener('click',()=>validatorSetOptions('recommended'));
  $('validatorAllBtn')?.addEventListener('click',()=>validatorSetOptions('all'));
  $('validatorNoneBtn')?.addEventListener('click',()=>validatorSetOptions('none'));
  $('validatorFixBtn')?.addEventListener('click',applyValidatorFixes);
  $('validatorDownloadBtn')?.addEventListener('click',downloadValidatorFixed);
  $('validatorImportBtn')?.addEventListener('click',importValidatorFixed);
  $('validatorFileInput')?.addEventListener('change',e=>prepareValidatorFiles(e.target.files));
  modal.addEventListener('click',e=>{if(e.target===modal)closeValidatorModal();});
  const dz=$('validatorDropzone');
  if(dz){
    dz.addEventListener('click',()=>$('validatorFileInput')?.click());
    ['dragenter','dragover'].forEach(type=>dz.addEventListener(type,e=>{e.preventDefault();e.stopPropagation();dz.classList.add('dragover');}));
    ['dragleave','drop'].forEach(type=>dz.addEventListener(type,e=>{e.preventDefault();e.stopPropagation();dz.classList.remove('dragover');}));
    dz.addEventListener('drop',e=>prepareValidatorFiles(e.dataTransfer?.files));
  }
}

function createSaveProjectPayload(){
  const center=MAP_RUNTIME.getCenter();
  return {
    kind:'polygon-editor-project',
    version:2,
    app:'Polygon Editor Tool',
    savedAt:new Date().toISOString(),
    files:clone(project.files||[]),
    measurements:clone(MEASURE.items||[]),
    imageOverlays:clone(IMAGE.overlays||[]).map(o=>{
      const c=normaliseImageOverlay(o);
      return {...c};
    }),
    selectedFileId:project.selectedFileId||null,
    selectedFeatureId:project.selectedFeatureId||null,
    selectedMeasurementId:MEASURE.selectedId||null,
    selectedImageId:IMAGE.selectedId||null,
    mergeIds:clone(project.mergeIds||[]),
    view:{center,zoom:MAP_RUNTIME.getZoom()},
    polygonMoveBehavior:project.polygonMoveBehavior||'screen',
    ui:{
      basemap:$('basemap')?.value||null,
      nightMode:document.body.classList.contains('night-mode'),
      polygonMoveBehavior:project.polygonMoveBehavior||'screen'
    }
  };
}
function saveProject(){
  const payload=createSaveProjectPayload();
  if(!projectPayloadHasContent(payload)){
    setStatus('Nothing to save yet. Add a polygon, annotation, measurement or image first.','error');
    return;
  }
  const counts={
    features:(payload.files||[]).reduce((s,f)=>s+(f.features||[]).length,0),
    measurements:(payload.measurements||[]).filter(i=>measureToolFamily(i.type)!=='annotation').length,
    annotations:(payload.measurements||[]).filter(i=>measureToolFamily(i.type)==='annotation').length,
    images:(payload.imageOverlays||[]).length
  };
  downloadText('polygon_editor_project.polygonproject',JSON.stringify(payload,null,2),'application/json;charset=utf-8');
  setDirty(false);
  writeAutosaveNow('manual-save');
  writeJournalNow();
  setStatus(`Saved editable project: ${counts.features} feature${counts.features===1?'':'s'}, ${counts.annotations} annotation${counts.annotations===1?'':'s'}, ${counts.measurements} measurement${counts.measurements===1?'':'s'}, ${counts.images} image${counts.images===1?'':'s'}.`);
}
