    <div class="layer-row-main">${v69ImageThumbHtml(o)}<div class="feature-main"><div class="feature-name">${o.locked?'[locked] ':''}${esc(o.name)}</div><div class="feature-meta">${((o.opacity??.65)*100|0)}% · ${esc(imageOverlayStateLabel(o))}</div></div></div>
