const __step2RenderSelected=renderSelected;
renderSelected=function(){
  __step2RenderSelected();
  const panel=$('selectedPanel');const r=ref();
  if(!panel||!r||!polygonSupported(getDisplayGeometry(r.feature)?.type))return;
  const holes=holeInfosForFeature(r.feature).length;
  const chipColor=(STEP2_STYLE_CLIPBOARD.style?.style?.fillColor||STEP2_STYLE_CLIPBOARD.style?.style?.color||'#1664d6');
  const card=document.createElement('div');
  card.className='inspector-card';
  card.innerHTML=`<h3>Holes, isolate & style</h3>
    <div class="inspector-grid"><div class="k">Holes</div><div>${holes}</div><div class="k">Style copied</div><div><span class="style-chip" style="--style-chip-color:${esc(chipColor)}">${STEP2_STYLE_CLIPBOARD.style?esc(STEP2_STYLE_CLIPBOARD.sourceName):'None'}</span></div></div>
    <div class="step2-inspector-grid" style="margin-top:8px">
      <button id="panelHoleManager">Hole manager</button>
      <button id="panelConvertPickedHoles">Picked → holes</button>
      <button id="panelSoloFeature">${isSoloFeatureId(r.feature.id)?'Unsolo':'Solo feature'}</button>
      <button id="panelUnsoloAll">Unsolo all</button>
      <button id="panelCopyStyle">Copy style</button>
      <button id="panelPasteStyle">Paste style</button>
      <button id="panelPastePicked">Paste to picked</button>
      <button id="panelPasteLayer">Paste to layer</button>
    </div>`;
  panel.appendChild(card);
  $('panelHoleManager')?.addEventListener('click',()=>openHoleManagerPanel(r.feature.id));
  $('panelConvertPickedHoles')?.addEventListener('click',convertPickedPolygonsToHoles);
  $('panelSoloFeature')?.addEventListener('click',()=>isSoloFeatureId(r.feature.id)?clearSolo():soloFeature(r.feature.id));
  $('panelUnsoloAll')?.addEventListener('click',clearSolo);
  $('panelCopyStyle')?.addEventListener('click',()=>copyStyleFromFeature(r.feature.id));
  $('panelPasteStyle')?.addEventListener('click',()=>pasteStyleToFeature(r.feature.id));
  $('panelPastePicked')?.addEventListener('click',pasteStyleToPickedOrSelected);
  $('panelPasteLayer')?.addEventListener('click',()=>pasteStyleToFile(r.file.id));
};

const __step2RenderOverlay=renderOverlay;
renderOverlay=function(){
  const ov=overlay();
  ov?.querySelectorAll('.hole-centre-handle').forEach(n=>n.remove());
  __step2RenderOverlay();
  if(!V.active||V.drag||V.edgeDrag||V.moveDrag||D.active||MEASURE.active)return;
  ov?.querySelectorAll('.vtx').forEach(n=>{try{const p=parseKey(n.__vkey||'');if(p.ringIndex>0)n.classList.add('hole-vtx');}catch{}});
  const refs=vertexEditRefs();
  if(!refs.length)return;
  const bounds=paddedPixelBounds();
  for(const r of refs){
    for(const info of holeInfosForFeature(r.feature)){
      if(!info.center)continue;
      const p=MAP_RUNTIME.latLngToPixel([info.center[1],info.center[0]]);
      if(!pointInPixelBounds(p,bounds))continue;
      const h=document.createElement('div');
      h.className='hole-centre-handle';
      h.title='Hole manager · click to manage this hole';
      h.style.left=p.x+'px';h.style.top=p.y+'px';
      h.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();openHoleManagerPanel(r.feature.id);});
      ov.appendChild(h);
    }
  }
};

// v49 phase 3: organised geometry UI, mode banners, fullscreen, safer states.
function toggleFullscreenEditor(){
  const app=document.querySelector('.app');
  if(!app){setStatus('Editor shell not found.','error');return;}
  const doc=document;
  try{
    if(!doc.fullscreenElement){
      const req=app.requestFullscreen||app.webkitRequestFullscreen||app.msRequestFullscreen;
      if(req){req.call(app);setStatus('Fullscreen editor mode. Press Esc to exit.');}
      else setStatus('Fullscreen is not supported by this browser.','error');
    }else{
      const exit=doc.exitFullscreen||doc.webkitExitFullscreen||doc.msExitFullscreen;
      if(exit)exit.call(doc);
    }
  }catch(err){setStatus('Fullscreen request failed.','error');}
}
window.toggleFullscreenEditor=toggleFullscreenEditor;
function syncFullscreenButton(){
  const active=!!document.fullscreenElement;
  document.body.classList.toggle('editor-fullscreen-active',active);
  const btn=$('fullscreenEditorBtn');
  if(btn){btn.textContent=active?'Exit full':'Fullscreen';btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',active?'true':'false');}
}
document.addEventListener('fullscreenchange',syncFullscreenButton);
$('fullscreenEditorBtn')?.addEventListener('click',toggleFullscreenEditor);
function geometryActionNeedsPicked(action){return ['merge','cut','intersect','clip','erase','polygonToHole'].includes(action);}
function geometryActionNeedsHoles(action){return action==='fillHoles';}
function refreshGeometryToolAvailability(){
  const sel=$('geometryActionSelect'); if(!sel)return;
  const r=ref();
  const selectedPoly=!!(r&&polygonSupported(getDisplayGeometry(r.feature)?.type)&&!isLocked(r.file,r.feature));
  const picked=(project.mergeIds||[]).filter(id=>id!==project.selectedFeatureId).map(id=>ref(id)).filter(Boolean);
  const hasPicked=!!picked.length;
  const holeCount=(selectedPoly&&r)?holeInfosForFeature(r.feature).length:0;
  Array.from(sel.options).forEach(o=>{
    if(!o.value){o.disabled=false;return;}
    let disabled=!selectedPoly;
    if(geometryActionNeedsPicked(o.value))disabled=disabled||!hasPicked;
    if(geometryActionNeedsHoles(o.value))disabled=disabled||holeCount<1;
    if(o.value==='drawHole')disabled=!selectedPoly;
    if(o.value==='splitLine')disabled=!selectedPoly;
    if(o.value==='offset'||o.value==='truncate'||o.value==='simplify'||o.value==='smooth'||o.value==='repair')disabled=!selectedPoly;
    o.disabled=!!disabled;
  });
  if(sel.value&&sel.selectedOptions?.[0]?.disabled){sel.value='';}
  const run=$('runGeometryBtn');
  if(run){
    const action=sel.value;
    const selectedDisabled=!!(action&&sel.selectedOptions?.[0]?.disabled);
    run.disabled=run.disabled||selectedDisabled||!selectedPoly;
    run.title=!selectedPoly?'Select an unlocked polygon first.':(geometryActionNeedsPicked(action)&&!hasPicked?'Ctrl/Shift-click at least one picked polygon first.':'Select a geometry tool to open its preview panel');
  }
}
function phase3ModeMessage(){
  if(D.active){
    const kind=D.kind||'polygon';
    return {
      kind:kind==='hole'?'hole':'draw',
      title:drawKindLabel(kind),
      hint:drawKindHint(kind)+' · Enter finishes · Backspace undoes · Esc cancels'
    };
  }
  if(V.active){
    return {
      kind:'vertex',
      title:V.moveDrag?'Moving polygon':(V.edgeDrag?'Moving edge':'Editing vertices'),
      hint:V.moveDrag?'Release to commit · Shift constrains 0°/45°/90°':'Drag centre cross-handle to move whole polygon · red vertices edit corners · green controls insert vertices · Esc exits'
    };
  }
  if(MEASURE.active){
    const name=measureDisplayName?.(MEASURE.type)||'Measurement';
    return {kind:MEASURE.type==='annotation'||MEASURE.type==='point'?'image':'measure',title:name,hint:'Click map points · Enter finishes · Backspace undoes · Esc cancels'};
  }
  if(GEOMETRY_OP.active&&GEOMETRY_OP.action){
    const cfg=geometryOpConfig(GEOMETRY_OP.action);
    if(cfg)return {kind:GEOMETRY_OP.action==='holeManager'||GEOMETRY_OP.action==='drawHole'||GEOMETRY_OP.action==='fillHoles'?'hole':'geometry',title:cfg.title,hint:cfg.description};
  }
  const img=imageOverlayById?.(IMAGE.selectedId);
  if(img){
    const label=imageOverlayStateLabel?.(img)||'Image overlay';
    return {kind:'image',title:'Image overlay',hint:label+' · use the image toolbar or inspector to move, resize, rotate or warp'};
  }
  if(STEP2_SOLO?.active){return {kind:'solo',title:'Solo mode active',hint:'Only the isolated layer/feature is visible · use Unsolo all to restore visibility'};}
  return null;
}
function refreshModeBanner(){
  const b=$('modeBanner'),t=$('modeBannerTitle'),h=$('modeBannerHint');
  const msg=phase3ModeMessage();
  if(!b||!t||!h)return;
  if(!msg){b.classList.remove('active');b.dataset.kind='';return;}
  t.textContent=msg.title;
  h.textContent=msg.hint;
  b.dataset.kind=msg.kind||'mode';
  b.classList.add('active');
}
function refreshPhase3Ui(){
  refreshGeometryToolAvailability();
  refreshModeBanner();
  document.body.classList.toggle('geometry-preview-open',$('geometryPreviewPanel')?.classList.contains('active'));
  document.body.classList.toggle('drawing-hole',D.active&&D.kind==='hole');
  syncFullscreenButton();
}
const __phase3RenderAll=renderAll;
renderAll=function(){const out=__phase3RenderAll.apply(this,arguments);requestAnimationFrame(refreshPhase3Ui);return out;};
const __phase3UpdateButtons=updateButtons;
updateButtons=function(){const out=__phase3UpdateButtons.apply(this,arguments);refreshPhase3Ui();return out;};
const __phase3EnsureInlineGeometryPreview=ensureInlineGeometryPreview;
ensureInlineGeometryPreview=function(action){
  const out=__phase3EnsureInlineGeometryPreview.apply(this,arguments);
  refreshPhase3Ui();
  return out;
};
const __phase3CloseInlineGeometryPreview=closeInlineGeometryPreview;
closeInlineGeometryPreview=function(){const out=__phase3CloseInlineGeometryPreview.apply(this,arguments);refreshPhase3Ui();return out;};
const __phase3ApplyGeometryOpFromModal=applyGeometryOpFromModal;
applyGeometryOpFromModal=function(){
  const action=GEOMETRY_OP.action||$('geometryActionSelect')?.value;
  if(action==='fillHoles'){
    const r=ref();
    const holes=r?holeInfosForFeature(r.feature).length:0;
    if(holes>0&&!confirm(`Fill all ${holes} hole${holes===1?'':'s'} in the active polygon? This is undoable with Ctrl+Z.`))return;
  }
  const out=__phase3ApplyGeometryOpFromModal.apply(this,arguments);
  refreshPhase3Ui();
  return out;
};
