// Rebind buttons after the preview-workflow overrides.
if($('runGeometryBtn'))$('runGeometryBtn').onclick=runGeometryAction;
if($('geometryPreviewApplyBtn'))$('geometryPreviewApplyBtn').onclick=applyGeometryOpFromModal;
if($('geometryPreviewUpdateBtn'))$('geometryPreviewUpdateBtn').onclick=updateInlineGeometryPreview;
if($('geometryOpApplyBtn'))$('geometryOpApplyBtn').onclick=applyGeometryOpFromModal;
if($('geometryOpPreviewBtn'))$('geometryOpPreviewBtn').onclick=updateGeometryPreview;


