  function v96StatHtml(k,v){return `<div class="v97-large-stat"><div class="k">${esc(k)}</div><div class="v">${esc(v)}</div></div>`;}
  function v101ImportFormatLabel(kind,stats={}){
    const raw=String(kind||stats.sourceFormat||stats.ext||'file').toLowerCase();
    const labels={geojson:'GeoJSON',json:'JSON',gml:'GML',kml:'KML',kmz:'KMZ',csv:'CSV',wkt:'WKT',txt:'WKT/TXT',zip:'Shapefile ZIP',shp:'Shapefile'};
    return labels[raw]||String(raw||'File').toUpperCase();
  }
  function v101LargeStatsHtml(stats,kind){
    const rows=[];
    rows.push(v96StatHtml('Source size',v96Bytes(stats.fileSize)));
    rows.push(v96StatHtml('Format',v101ImportFormatLabel(kind,stats)));
    if(stats.kmlBytes)rows.push(v96StatHtml('Unzipped KML text',v96Bytes(stats.kmlBytes)));
    if(stats.kmlCount)rows.push(v96StatHtml('KML files',v96Fmt(stats.kmlCount)));
    if(stats.featureCount!=null)rows.push(v96StatHtml('Features',v96Fmt(stats.featureCount)));
    else if(stats.placemarkCount!=null)rows.push(v96StatHtml('Placemarks',v96Fmt(stats.placemarkCount)));
    if(stats.coordinateCount!=null)rows.push(v96StatHtml('Coordinate values',`about ${v96Fmt(stats.coordinateCount)}`));
    rows.push(v96StatHtml('Recommended mode','Optimised editable'));
    return rows.join('');
  }
  function v96LargeImportOptionHtml(value,title,desc,tag,checked=false){
    return `<label class="v97-import-option ${checked?'selected':''}" data-v97-mode="${esc(value)}">
      <input type="radio" name="v97LargeImportMode" value="${esc(value)}" ${checked?'checked':''}/>
      <span><strong>${esc(title)}</strong><span class="subtle">${esc(desc)}</span><br/><span class="tag">${esc(tag)}</span></span>
    </label>`;
  }
  function v96ChooseMode(stats,kind){
    if(!stats.large)return Promise.resolve('normal');
    v96EnsureLargeImportStyles();
    return new Promise(resolve=>{
      let resolved=false;
      const backdrop=document.createElement('div');
      backdrop.className='modal-backdrop active';
      backdrop.id='v97LargeImportModal';
      backdrop.innerHTML=`<div aria-modal="true" class="modal v97-large-import-modal" role="dialog" aria-labelledby="v97LargeImportTitle">
        <div class="modal-head"><h2 id="v97LargeImportTitle">Large file import</h2><button type="button" id="v97LargeClose">Close</button></div>
        <div class="modal-body">
          <div class="v97-large-import-intro"><div class="ico">!</div><div><strong>${esc(stats.fileName)}</strong><br/>This file is large or complex enough that importing it as full editable geometry may freeze the browser. Choose how the app should handle it before it is added to the project.</div></div>
          <div class="v97-large-summary">
            ${v101LargeStatsHtml(stats,kind)}
          </div>
          <div class="v97-import-options">
            ${v96LargeImportOptionHtml('optimized','Optimised editable import','Imports an editable copy but simplifies very dense geometry before it reaches the map renderer and layer panel.','recommended',true)}
            ${v96LargeImportOptionHtml('reference','Reference overlay only','Adds a full-detail non-editable overlay through the existing Reference overlays system. It uses canvas rendering, so the source polygon is not simplified.','full detail')}
            ${v96LargeImportOptionHtml('sleeping','Optimised, start hidden/sleeping','Imports an optimised editable copy but leaves the layer hidden so it does not render until you intentionally enable it.','safest editable')}
            ${v96LargeImportOptionHtml('full','Full editable import','Runs the normal full-detail import. Use only if you need every original vertex immediately and are prepared for a possible browser freeze.','high risk')}
          </div>
          <div class="v97-large-import-warning">For large vector files, the app keeps editable imports grouped and collapsed where possible. Reference overlay mode uses the existing overlay system; it does not create a duplicate overlay manager.</div>
        </div>
        <div class="modal-foot"><button type="button" id="v97LargeCancel">Cancel import</button><button type="button" class="primary" id="v97LargeContinue">Continue</button></div>
      </div>`;
      document.body.appendChild(backdrop);
      const finish=(mode)=>{if(resolved)return;resolved=true;document.removeEventListener('keydown',onKey,true);backdrop.remove();resolve(mode);};
      const onKey=(ev)=>{if(ev.key==='Escape'){ev.preventDefault();finish('cancel');}};
      document.addEventListener('keydown',onKey,true);
      const refresh=()=>{
        const current=backdrop.querySelector('input[name="v97LargeImportMode"]:checked')?.value||'optimized';
        backdrop.querySelectorAll('.v97-import-option').forEach(el=>el.classList.toggle('selected',el.dataset.v97Mode===current));
      };
      backdrop.querySelectorAll('.v97-import-option').forEach(el=>{
        el.addEventListener('click',()=>{const input=el.querySelector('input');if(input){input.checked=true;refresh();}});
      });
      backdrop.querySelectorAll('input[name="v97LargeImportMode"]').forEach(input=>input.addEventListener('change',refresh));
      backdrop.querySelector('#v97LargeClose').onclick=()=>finish('cancel');
      backdrop.querySelector('#v97LargeCancel').onclick=()=>finish('cancel');
      backdrop.querySelector('#v97LargeContinue').onclick=()=>finish(backdrop.querySelector('input[name="v97LargeImportMode"]:checked')?.value||'optimized');
      refresh();
      setTimeout(()=>{try{backdrop.querySelector('#v97LargeContinue').focus();}catch(_){ }},0);
    });
  }

  async function v96BuildFeaturesFromTexts(texts,stats,mode,onProgress=()=>{}){
    const raw=[];
    for(let i=0;i<texts.length;i++){
      const item=texts[i];
      onProgress(`Reading ${item.path} with large-file parser (${i+1} of ${texts.length})…`,42+(i/texts.length)*30);
      const part=await v96FastKmlToFeatures(item.text,item.path,stats,mode,onProgress);
      raw.push(...part);
      onProgress(`Prepared ${v96Fmt(raw.length)} feature${raw.length===1?'':'s'} from ${item.path}…`,42+((i+1)/texts.length)*30);
      await v96Yield();
    }
    return raw;
  }
