    const raw=String(file?.sourceFormat||'geojson').toLowerCase();
    const labels={geojson:'GeoJSON',json:'JSON / GeoJSON',gml:'GML',kml:'KML',kmz:'KMZ',csv:'CSV',wkt:'WKT',txt:'WKT / text',topojson:'TopoJSON',zip:'Shapefile ZIP',shp:'Shapefile',validator:'Validator result',project:'Project file'};
