showAutosaveRecoveryIfAvailable();
;

/* ---- inline-script ---- */
(()=>{
  function initCompactTopbarMenu(){
    const btn=document.getElementById('topMoreBtn');
    const menu=document.getElementById('topMoreMenu');
    if(!btn||!menu)return;
    function close(){menu.classList.remove('active');btn.setAttribute('aria-expanded','false');}
    function toggle(e){e.preventDefault();e.stopPropagation();const open=!menu.classList.contains('active');menu.classList.toggle('active',open);btn.setAttribute('aria-expanded',open?'true':'false');}
    btn.addEventListener('click',toggle);
    const syncSelect=(fromId,toId)=>{const from=document.getElementById(fromId),to=document.getElementById(toId);if(from&&to){from.value=to.value;from.addEventListener('change',()=>{to.value=from.value;});to.addEventListener('change',()=>{from.value=to.value;});}};
    syncSelect('topMenuExportScope','exportScope');
    syncSelect('topMenuExportFormat','exportFormat');
    document.getElementById('topMenuSaveProxy')?.addEventListener('click',()=>document.getElementById('saveBtn')?.click());
    document.getElementById('topMenuFitProxy')?.addEventListener('click',()=>document.getElementById('fitAllBtn')?.click());
    document.getElementById('topMenuExportProxy')?.addEventListener('click',()=>document.getElementById('exportBtn')?.click());
    document.getElementById('topMenuCommandProxy')?.addEventListener('click',()=>{close();window.openCommandPalette?.();});
    menu.addEventListener('click',e=>{
      const interactive=e.target.closest('select,input');
      if(interactive)return;
      const clickedButton=e.target.closest('button');
      if(clickedButton) setTimeout(close,0);
    });
    document.addEventListener('pointerdown',e=>{if(!menu.contains(e.target)&&e.target!==btn)close();},true);
    document.addEventListener('keydown',e=>{if(e.key==='Escape')close();},true);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initCompactTopbarMenu);
  else initCompactTopbarMenu();
})();
;

/* ---- inline-script ---- */
(()=>{
  const STORAGE_KEY='polygonEditorTheme';
  const PREV_BASEMAP_KEY='polygonEditorPreviousBasemap';
  function $(id){return document.getElementById(id);}
  function setBasemap(value){
    const select=$('basemap');
    if(!select || !value || !Array.from(select.options).some(o=>o.value===value)) return;
    if(select.value!==value){
      select.value=value;
      select.dispatchEvent(new Event('change',{bubbles:true}));
    }
  }
  function currentBasemap(){return $('basemap')?.value || 'osm';}
  function syncButton(isNight){
    const btn=$('themeToggleBtn');
    if(!btn) return;
    btn.textContent=isNight?'Day':'Night';
    btn.classList.toggle('active',isNight);
    btn.setAttribute('aria-pressed',isNight?'true':'false');
    btn.title=isNight?'Switch to day mode':'Switch to night mode';
  }
  function applyTheme(mode, opts={}){
    const isNight=mode==='night';
    document.body.classList.toggle('night-mode',isNight);
    document.documentElement.style.colorScheme=isNight?'dark':'light';
    try{localStorage.setItem(STORAGE_KEY,isNight?'night':'day');}catch(err){}
    syncButton(isNight);
    const base=currentBasemap();
    if(opts.updateBasemap!==false){
      if(isNight){
        if(base!=='dark'){
          try{localStorage.setItem(PREV_BASEMAP_KEY,base);}catch(err){}
          setBasemap('dark');
        }
      }else if(base==='dark'){
        let prev='osm';
        try{prev=localStorage.getItem(PREV_BASEMAP_KEY)||'osm';}catch(err){}
        if(prev==='dark') prev='osm';
        setBasemap(prev);
      }
    }
  }
  window.setPolygonEditorTheme=applyTheme;
  function initNightMode(){
    const btn=$('themeToggleBtn');
    if(btn){
      btn.addEventListener('click',()=>{
        const night=!document.body.classList.contains('night-mode');
        applyTheme(night?'night':'day');
      });
    }
    const stored=(()=>{try{return localStorage.getItem(STORAGE_KEY);}catch(err){return null;}})();
    applyTheme(stored==='night'?'night':'day',{updateBasemap:stored==='night'});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initNightMode);
  else initNightMode();
})();


// v50: persistent mode system, active controls, stronger selection and interaction safety.
(function(){
  function safe$(id){try{return $(id)}catch(_){return document.getElementById(id)}}
  function isInlinePreviewOpen(){return !!(safe$('geometryPreviewPanel')?.classList.contains('active'));}
  function drawMetricText(){
    if(!D?.active)return '';
    try{
      const m=drawMetrics?.();
      const parts=[];
      if(D.points?.length)parts.push(`${D.points.length} point${D.points.length===1?'':'s'}`);
      if(m?.area!=null && typeof areaLabel==='function')parts.push(areaLabel(m.area));
      if(m?.perim!=null && typeof lenLabel==='function')parts.push(`${lenLabel(m.perim)} perimeter`);
      return parts.join(' · ');
    }catch(_){return D.points?.length?`${D.points.length} point${D.points.length===1?'':'s'}`:'';}
  }
  function measureCanFinish(){
    if(!MEASURE?.active)return false;
    const min={distance:2,area:3,point:1,annotation:1}[MEASURE.type]||2;
    return (MEASURE.points||[]).length>=min;
  }
  function drawInstruction(){
    const kind=D.kind||'polygon';
    const n=(D.points||[]).length;
    if(kind==='rectangle')return n?'Move pointer to preview, then click opposite corner · Shift forces square':'Click the first corner · Esc cancels';
    if(kind==='circle')return n?'Move pointer to set radius, then click to create circle':'Click the centre point · Esc cancels';
    if(kind==='regular')return n?'Move pointer to set radius/orientation, then click · Shift snaps orientation':'Click the centre point · Esc cancels';
    if(kind==='rotatedRect')return n<1?'Click the first corner · Esc cancels':(n<2?'Click end of first edge · Shift snaps angle':'Move pointer to set width, then click');
    if(kind==='freehand')return D.dragging?'Release mouse to create freehand polygon':'Press and drag to sketch · Esc cancels';
    if(kind==='buffer')return n?'Click more centreline points · Finish/Enter builds corridor · Shift snaps angles':'Click centreline points · set width in the draw bar';
    if(kind==='split')return n?'Click more split-line points · Finish/Enter applies split · Shift snaps angles':'Click a line through the active polygon';
    if(kind==='hole')return n?'Click more hole points · Finish/Enter cuts hole · Shift snaps angles':'Click points inside the active polygon to draw a hole';
    return n?'Click more points · Finish/Enter creates polygon · Backspace undoes':'Click map to add first point · Shift snaps edge angles';
  }
  function selectionInstruction(){
    const r=ref?.();
    if(r&&polygonSupported?.(getDisplayGeometry(r.feature)?.type))return `Selected: ${r.feature.name} · click Edit polygon for centre move/vertex/edge handles, or use Geometry tools`;
    if(imageOverlayById?.(IMAGE?.selectedId))return 'Image selected · use the image toolbar or inspector to move, resize, rotate, stretch or warp';
    return 'Select a polygon, choose a Draw shape, or press Ctrl+K for commands';
  }
  function v50ModeMessage(){
    if(D?.active){
      const kind=D.kind||'polygon';
      return {kind:kind==='hole'?'hole':'draw',title:drawKindLabel?.(kind)||'Drawing',hint:drawInstruction(),metric:drawMetricText(),primary:'Finish',primaryEnabled:!!drawCanFinish?.(),secondary:'Cancel',secondaryEnabled:true};
    }
    if(V?.active){
      let title='Editing vertices',hint='Drag centre cross-handle to move whole polygon · red vertices move corners · green midpoints insert vertices · blue edge bands slide edges · Esc exits';
      if(V.moveDrag){title='Moving polygon';hint='Release to commit · Shift constrains movement to 0°/45°/90°';}
      else if(V.edgeDrag){title='Moving edge';hint='Move perpendicular to slide the edge parallel · release to commit';}
      else if(V.drag){title='Moving vertex';hint='Release to commit vertex position · Alt temporarily disables snapping';}
      else if(V.lasso){title='Vertex lasso';hint='Drag a box around vertices, then delete or move selected vertices';}
      return {kind:'vertex',title,hint,metric:`${V.selected?.size||0} selected`,primary:'Done',primaryEnabled:true,secondary:'Exit',secondaryEnabled:true};
    }
    if(MEASURE?.active){
      const name=measureDisplayName?.(MEASURE.type)||'Measurement';
      const pts=MEASURE.points?.length||0;
      const finish=measureToolFamily?.(MEASURE.type)==='annotation'?'Place':'Finish';
      return {kind:'measure',title:name,hint:'Click map points · Finish/Enter saves when enough points are placed · Backspace undoes · Esc cancels',metric:pts?`${pts} point${pts===1?'':'s'}`:'',primary:finish,primaryEnabled:measureCanFinish(),secondary:'Cancel',secondaryEnabled:true};
    }
    if(isInlinePreviewOpen()&&GEOMETRY_OP?.action){
      const cfg=geometryOpConfig?.(GEOMETRY_OP.action);
      return {kind:'preview',title:cfg?.title||'Geometry preview',hint:cfg?.description||'Review the preview, then apply or cancel.',metric:'Preview active',primary:'Apply',primaryEnabled:true,secondary:'Cancel',secondaryEnabled:true};
    }
    const img=imageOverlayById?.(IMAGE?.selectedId);
    if(img){
      return {kind:'image',title:'Image overlay',hint:(imageOverlayStateLabel?.(img)||'Image selected')+' · handles edit image placement; Esc deselects',metric:img.locked?'Locked':'',primary:'Deselect',primaryEnabled:true,secondary:'Cancel',secondaryEnabled:false};
    }
    if(STEP2_SOLO?.active){
      return {kind:'solo',title:'Solo mode active',hint:'Only the isolated layer/feature is visible. Restore previous visibility when finished.',metric:'Isolated view',primary:'Unsolo all',primaryEnabled:true,secondary:'',secondaryEnabled:false};
    }
    return {kind:'select',title:'Select mode',hint:selectionInstruction(),metric:'',primary:'',primaryEnabled:false,secondary:'',secondaryEnabled:false};
  }
  window.v50ModeMessage=v50ModeMessage;
  window.refreshModeBanner=function(){
    const b=safe$('modeBanner'),t=safe$('modeBannerTitle'),h=safe$('modeBannerHint'),m=safe$('modeBannerMetric'),p=safe$('modeBannerFinishBtn'),c=safe$('modeBannerCancelBtn');
    if(!b||!t||!h)return;
    const msg=v50ModeMessage();
    t.textContent=msg.title||'Select mode';
    h.textContent=msg.hint||'';
    if(m)m.textContent=msg.metric||'';
    b.dataset.kind=msg.kind||'select';
    b.classList.add('active');
    if(p){p.textContent=msg.primary||'Finish';p.disabled=!msg.primaryEnabled;p.style.display=msg.primaryEnabled?'inline-flex':'none';}
    if(c){c.textContent=msg.secondary||'Cancel';c.disabled=!msg.secondaryEnabled;c.style.display=msg.secondaryEnabled?'inline-flex':'none';}
  };
  function cancelActiveMode(){
    if(D?.active){DCancel(false);return true;}
    if(V?.active){VStop(false);return true;}
    if(MEASURE?.active){cancelMeasure(false);return true;}
    if(MOVE?.active){stopPolygonMoveMode(false);return true;}
    if(isInlinePreviewOpen()){closeInlineGeometryPreview?.();return true;}
    if(imageOverlayById?.(IMAGE?.selectedId)){IMAGE.selectedId=null;renderAll?.();setStatus?.('Image overlay deselected.');return true;}
    return false;
  }
  function finishActiveMode(){
    if(D?.active){DFinish();return true;}
    if(V?.active){VStop(false);return true;}
    if(MEASURE?.active){finishMeasure();return true;}
    if(isInlinePreviewOpen()){applyGeometryOpFromModal?.();return true;}
    if(STEP2_SOLO?.active&&typeof unsoloAll==='function'){unsoloAll();return true;}
    if(imageOverlayById?.(IMAGE?.selectedId)){IMAGE.selectedId=null;renderAll?.();setStatus?.('Image overlay deselected.');return true;}
    return false;
  }
  safe$('modeBannerCancelBtn')?.addEventListener('click',e=>{e.preventDefault();cancelActiveMode();});
  safe$('modeBannerFinishBtn')?.addEventListener('click',e=>{e.preventDefault();finishActiveMode();});
  document.addEventListener('keydown',e=>{
    if(e.key!=='Escape'||e.defaultPrevented)return;
    const target=e.target;
    if(target&&target.closest&&target.closest('.modal.active,.command-modal.active,.layer-menu.active,.pick-menu.active'))return;
    if(cancelActiveMode()){e.preventDefault();e.stopPropagation();}
  });
  document.addEventListener('keydown',e=>{
    if(e.key!=='Enter'||e.defaultPrevented)return;
    const tag=document.activeElement?.tagName;
    const typing=tag==='INPUT'||tag==='TEXTAREA'||document.activeElement?.isContentEditable;
    if(typing)return;
    if((D?.active||MEASURE?.active)&&finishActiveMode()){e.preventDefault();e.stopPropagation();}
  });
  const oldRefreshPhase3=typeof window.refreshPhase3Ui==='function'?window.refreshPhase3Ui:null;
  window.refreshPhase3Ui=function(){
    try{oldRefreshPhase3?.();}catch(_){ }
    try{refreshGeometryToolAvailability?.();}catch(_){ }
    refreshModeBanner();
    const kind=D?.active?(D.kind||'polygon'):'';
    document.body.classList.toggle('mode-draw-active',!!D?.active);
    document.body.classList.toggle('mode-draw-freehand',!!D?.active&&kind==='freehand');
    document.body.classList.toggle('mode-geometry-preview',isInlinePreviewOpen());
    document.body.classList.toggle('mode-image-active',!!imageOverlayById?.(IMAGE?.selectedId));
    document.body.classList.toggle('mode-solo-active',!!STEP2_SOLO?.active);
    document.body.classList.toggle('mode-has-active-tool',!!(D?.active||V?.active||MEASURE?.active||MOVE?.active||isInlinePreviewOpen()));
  };
  const oldCustom=window.customPointerDragActive||customPointerDragActive;
  window.customPointerDragActive=function(){
    return !!(V?.drag||V?.edgeDrag||V?.moveDrag||IMAGE?.drag||(MEASURE?.active&&MEASURE?.drawing)||D?.active||(V?.active&&V?.lassoDrawing)||oldCustom?.());
  };
  // Function declarations are writable in this app; update the local binding used by the pan guard too.
  try{customPointerDragActive=window.customPointerDragActive;}catch(_){ }
  const oldStyle=style;
  window.style=style=function(f){
    const s=oldStyle(f)||{};
    if(f?.id===project.selectedFeatureId){
      return {...s,color:'#d22f27',fillColor:'#d22f27',weight:3,opacity:1,fillOpacity:s.fillOpacity??.16};
    }
    if(project.mergeIds?.includes(f?.id))return {...s,weight:3,opacity:1};
    return s;
  };
  const oldUpdateButtons=updateButtons;
  window.updateButtons=updateButtons=function(){const out=oldUpdateButtons.apply(this,arguments);try{refreshModeBanner();}catch(_){ }return out;};
  const oldRenderAll=renderAll;
  window.renderAll=renderAll=function(){const out=oldRenderAll.apply(this,arguments);requestAnimationFrame(()=>{try{refreshPhase3Ui();}catch(_){ }});return out;};
  requestAnimationFrame(()=>{try{refreshPhase3Ui();}catch(_){ }});
})();


// v51: active-mode toolbar clarity fix.
// Keeps the mode bar, hides duplicated selected toolbar during active modes,
// and routes Finish/Cancel through the real mode functions before Leaflet can steal the click.
(function(){
  function q(id){return document.getElementById(id)}
  function hasDrawSettings(){
    try{return !!(D && D.active && ['circle','regular','buffer'].includes(D.kind||'polygon'));}
    catch(_){return false;}
  }
  function syncModeClasses(){
    try{
      const draw=!!(D&&D.active), vertex=!!(V&&V.active), measure=!!(MEASURE&&MEASURE.active), image=!!(IMAGE&&imageOverlayById&&imageOverlayById(IMAGE.selectedId));
      const preview=!!(q('geometryPreviewPanel')&&q('geometryPreviewPanel').classList.contains('active'));
      const solo=!!(typeof STEP2_SOLO!=='undefined'&&STEP2_SOLO&&STEP2_SOLO.active);
      document.body.classList.toggle('draw-active',draw);
      document.body.classList.toggle('vertex-editing',vertex);
      document.body.classList.toggle('measure-active',measure);
      document.body.classList.toggle('image-overlay-selected',image);
      document.body.classList.toggle('mode-draw-active',draw);
      document.body.classList.toggle('mode-draw-has-settings',hasDrawSettings());
      document.body.classList.toggle('mode-geometry-preview',preview);
      document.body.classList.toggle('mode-image-active',image);
      document.body.classList.toggle('mode-solo-active',solo);
      document.body.classList.toggle('mode-has-active-tool',!!(draw||vertex||measure||preview||image||solo));
    }catch(_){ }
  }
  function refreshModeBar(){
    try{ if(typeof window.refreshModeBanner==='function') window.refreshModeBanner(); }
    catch(_){ }
    syncModeClasses();
  }
  function cancelMode(){
    try{
      if(D&&D.active){DCancel(false);syncModeClasses();return true;}
      if(V&&V.active){VStop(false);syncModeClasses();return true;}
      if(MEASURE&&MEASURE.active){cancelMeasure(false);syncModeClasses();return true;}
      if(typeof MOVE!=='undefined'&&MOVE&&MOVE.active){stopPolygonMoveMode(false);syncModeClasses();return true;}
      if(q('geometryPreviewPanel')&&q('geometryPreviewPanel').classList.contains('active')){closeInlineGeometryPreview&&closeInlineGeometryPreview();syncModeClasses();return true;}
      if(typeof IMAGE!=='undefined'&&IMAGE&&imageOverlayById&&imageOverlayById(IMAGE.selectedId)){IMAGE.selectedId=null;renderAll&&renderAll();setStatus&&setStatus('Image overlay deselected.');syncModeClasses();return true;}
    }catch(err){console.warn('Cancel active mode failed',err);}
    return false;
  }
  function finishMode(){
    try{
      if(D&&D.active){DFinish();syncModeClasses();return true;}
      if(V&&V.active){VStop(false);syncModeClasses();return true;}
      if(MEASURE&&MEASURE.active){finishMeasure();syncModeClasses();return true;}
      if(q('geometryPreviewPanel')&&q('geometryPreviewPanel').classList.contains('active')){applyGeometryOpFromModal&&applyGeometryOpFromModal();syncModeClasses();return true;}
      if(typeof STEP2_SOLO!=='undefined'&&STEP2_SOLO&&STEP2_SOLO.active&&typeof unsoloAll==='function'){unsoloAll();syncModeClasses();return true;}
      if(typeof IMAGE!=='undefined'&&IMAGE&&imageOverlayById&&imageOverlayById(IMAGE.selectedId)){IMAGE.selectedId=null;renderAll&&renderAll();setStatus&&setStatus('Image overlay deselected.');syncModeClasses();return true;}
    }catch(err){console.warn('Finish active mode failed',err);}
    return false;
  }
  function hardWire(btn,fn){
    if(!btn)return;
    ['pointerdown','mousedown','touchstart'].forEach(type=>btn.addEventListener(type,function(e){e.preventDefault();e.stopPropagation();},true));
    btn.addEventListener('click',function(e){
      e.preventDefault();
      e.stopPropagation();
      if(e.stopImmediatePropagation)e.stopImmediatePropagation();
      fn();
      requestAnimationFrame(refreshModeBar);
    },true);
  }
  hardWire(q('modeBannerFinishBtn'),finishMode);
  hardWire(q('modeBannerCancelBtn'),cancelMode);
  ['drawSegmentsInput','drawSidesInput','drawBufferWidthInput'].forEach(id=>{
    const el=q(id);
    if(el)el.addEventListener('input',()=>requestAnimationFrame(refreshModeBar));
  });
  const oldRefresh=window.refreshModeBanner;
  window.refreshModeBanner=function(){
    let out;
    try{out=oldRefresh&&oldRefresh.apply(this,arguments);}catch(_){ }
    syncModeClasses();
    return out;
  };
  const oldRender=window.renderAll;
  if(typeof oldRender==='function'){
    window.renderAll=renderAll=function(){
      const out=oldRender.apply(this,arguments);
      requestAnimationFrame(syncModeClasses);
      return out;
    };
  }
  const oldUpdate=window.updateButtons;
  if(typeof oldUpdate==='function'){
    window.updateButtons=updateButtons=function(){
      const out=oldUpdate.apply(this,arguments);
      syncModeClasses();
      return out;
    };
  }
  document.addEventListener('pointerdown',function(e){
    if(e.target&&e.target.closest&&e.target.closest('#modeBanner,#drawFloatToolbar,#vertexFloatToolbar,#measureFloatToolbar,#imageOverlayToolbar')){
      e.stopPropagation();
    }
  },true);
  requestAnimationFrame(refreshModeBar);
})();
;

/* ---- inline-script ---- */
// v60: geometry preview commit wording and controls cleanup --------------------
// The geometry panel auto-refreshes whenever parameters change, so the old
// "Update preview" button was redundant. The commit button is now named "Run"
// because some geometry actions start a draw workflow rather than applying an
// immediate result.
(function(){
  function $(id){return document.getElementById(id)}
  function v60ScrubGeometryText(){
    const ids=['geometryPreviewDesc','geometryPreviewSummary','geometryPreviewImpact','geometryOpDescription','geometryOpSummary','geometryOpWarning'];
    for(const id of ids){
      const el=$(id); if(!el)continue;
      el.innerHTML=el.innerHTML
        .replace(/Click Apply/g,'Click Run')
        .replace(/click Apply/g,'click Run')
        .replace(/then click Apply/g,'then click Run')
        .replace(/until you click Apply/g,'until you click Run')
        .replace(/Apply starts/g,'Run starts')
        .replace(/Apply will/g,'Run will')
        .replace(/Click the Apply button/g,'Click Run')
        .replace(/click the Apply button/g,'click Run');
    }
  }
  function v60SetGeometryRunUi(mode){
    const previewBtn=$('geometryPreviewUpdateBtn');
    const runBtn=$('geometryPreviewApplyBtn');
    const modalPreviewBtn=$('geometryOpPreviewBtn');
    const modalRunBtn=$('geometryOpApplyBtn');
    const isHoleManager=mode==='holeManager';
    if(previewBtn){
      if(isHoleManager){previewBtn.hidden=false;previewBtn.removeAttribute('aria-hidden');previewBtn.tabIndex=0;previewBtn.style.display='inline-flex';previewBtn.textContent='Refresh';}
      else{previewBtn.hidden=true;previewBtn.setAttribute('aria-hidden','true');previewBtn.tabIndex=-1;previewBtn.style.display='none';previewBtn.textContent='Update preview';}
    }
    if(runBtn && !isHoleManager)runBtn.textContent='Run';
    if(modalPreviewBtn){modalPreviewBtn.hidden=true;modalPreviewBtn.setAttribute('aria-hidden','true');modalPreviewBtn.tabIndex=-1;modalPreviewBtn.style.display='none';}
    if(modalRunBtn)modalRunBtn.textContent='Run';
    v60ScrubGeometryText();
  }
  window.v60SetGeometryRunUi=v60SetGeometryRunUi;
  const bind=()=>{
    v60SetGeometryRunUi();
    // Wrap preview functions after the app has defined them.
    if(typeof window.ensureInlineGeometryPreview==='function' && !window.ensureInlineGeometryPreview.__v60Wrapped){
      const base=window.ensureInlineGeometryPreview;
      window.ensureInlineGeometryPreview=function(action){
        const out=base.apply(this,arguments);
        v60SetGeometryRunUi(action);
        return out;
      };
      window.ensureInlineGeometryPreview.__v60Wrapped=true;
    }
    if(typeof window.updateInlineGeometryPreview==='function' && !window.updateInlineGeometryPreview.__v60Wrapped){
      const base=window.updateInlineGeometryPreview;
      window.updateInlineGeometryPreview=function(){
        const out=base.apply(this,arguments);
        const action=(window.GEOMETRY_OP&&window.GEOMETRY_OP.action)||$('geometryActionSelect')?.value;
        v60SetGeometryRunUi(action);
        return out;
      };
      window.updateInlineGeometryPreview.__v60Wrapped=true;
    }
    if(typeof window.openHoleManagerPanel==='function' && !window.openHoleManagerPanel.__v60Wrapped){
      const base=window.openHoleManagerPanel;
      window.openHoleManagerPanel=function(){
        const out=base.apply(this,arguments);
        v60SetGeometryRunUi('holeManager');
        const runBtn=$('geometryPreviewApplyBtn');
        if(runBtn)runBtn.textContent='Close';
        return out;
      };
      window.openHoleManagerPanel.__v60Wrapped=true;
    }
    if(typeof window.closeInlineGeometryPreview==='function' && !window.closeInlineGeometryPreview.__v60Wrapped){
      const base=window.closeInlineGeometryPreview;
      window.closeInlineGeometryPreview=function(){
        const out=base.apply(this,arguments);
        v60SetGeometryRunUi();
        return out;
      };
      window.closeInlineGeometryPreview.__v60Wrapped=true;
    }
  };
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind); else bind();
  // A final pass after all inline initialisers and previous version overrides run.
  setTimeout(bind,0);
})();
;

/* ---- v61LayerIconControlsScript ---- */
// v61 layer list icon controls: SVG/glyph controls instead of text badges.
(function(){
  function iconSvg(name){
    if(name==='polygon')return '<svg class="v61-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8 L12 4 L19 9 L17 18 L8 19 Z"></path></svg>';
    if(name==='multipolygon')return '<svg class="v61-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 9 L11 5 L17 8 L15 15 L8 16 Z"></path><path d="M9 11 L15 8 L20 12 L18 19 L11 20 Z"></path></svg>';
    if(name==='line')return '<svg class="v61-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 17 L9 9 L15 13 L20 6"></path><circle class="fill" cx="4" cy="17" r="1.6"></circle><circle class="fill" cx="20" cy="6" r="1.6"></circle></svg>';
    if(name==='point')return '<svg class="v61-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4.5"></circle><path d="M12 3 V6 M12 18 V21 M3 12 H6 M18 12 H21"></path></svg>';
    if(name==='issue')return '<svg class="v61-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4 L21 20 H3 Z"></path><path d="M12 9 V14"></path><path d="M12 17 H12.1"></path></svg>';
    if(name==='image')return '<svg class="v61-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5" width="16" height="14" rx="1"></rect><path d="M7 16 L10.2 12.8 L12.6 15.2 L15.8 12 L20 16"></path><circle cx="9" cy="9" r="1.2"></circle></svg>';
    if(name==='ruler')return '<svg class="v61-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 17 L17 5 L20 8 L8 20 Z"></path><path d="M10 16 L8 14 M13 13 L11 11 M16 10 L14 8"></path></svg>';
    if(name==='area')return '<svg class="v61-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 7 L14 5 L19 11 L16 19 L7 17 Z"></path><path d="M8 12 H16"></path></svg>';
    return '<svg class="v61-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="5" width="14" height="14"></rect></svg>';
  }
  function controlIcon(name){
    if(name==='check')return '<svg viewBox="0 0 24 24" aria-hidden="true"><rect class="v61-check-fill" x="5" y="5" width="14" height="14"></rect><rect class="v61-check-box" x="5" y="5" width="14" height="14"></rect><path class="v61-check-mark" d="M8 12.5 L11 15.5 L17 8.5"></path></svg>';
    if(name==='eye')return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3.5 12 C6 7.5 9 5.5 12 5.5 C15 5.5 18 7.5 20.5 12 C18 16.5 15 18.5 12 18.5 C9 18.5 6 16.5 3.5 12 Z"></path><circle cx="12" cy="12" r="2.5"></circle><path class="slash" d="M5 20 L19 4"></path></svg>';
    if(name==='lock')return '<svg viewBox="0 0 24 24" aria-hidden="true"><path class="shackle-closed" d="M8 10 V8 C8 5.8 9.6 4.5 12 4.5 C14.4 4.5 16 5.8 16 8 V10"></path><path class="shackle-open" d="M8 10 V8 C8 5.8 9.6 4.5 12 4.5 C13.9 4.5 15.1 5.3 15.7 6.7"></path><rect x="6" y="10" width="12" height="10"></rect><path d="M12 14 V16"></path></svg>';
    return '';
  }
  window.v61LayerIconSvg=iconSvg;
  window.v61LayerControlSvg=controlIcon;
  window.v54FeatureBadge=function(f){
    const t=(typeof getDisplayGeometry==='function'?(getDisplayGeometry(f)?.type):null)||f.geometry?.type||'Feature';
    let cls='poly', icon='polygon', label='Polygon';
    if(t==='MultiPolygon'){cls='multi';icon='multipolygon';label='MultiPolygon';}
    else if(t==='LineString'||t==='MultiLineString'){cls='line';icon='line';label='Line';}
    else if(t==='Point'||t==='MultiPoint'){cls='point';icon='point';label='Point';}
    let invalid=false;
    try{const v=v53ValiditySummary?.(f);invalid=!!(v&&v.cls==='warn'&&polygonSupported(getDisplayGeometry(f)?.type));}catch{}
    if(invalid){cls+=' invalid';icon='issue';label='Geometry issue';}
    return `<span class="v54-geom-badge ${cls}" title="${esc(label)}">${iconSvg(icon)}<span>${esc(label)}</span></span>`;
  };
  const oldEnhance = window.v54EnhanceLayerRows;
  window.v54EnhanceLayerRows = v54EnhanceLayerRows = function(){
    if(typeof oldEnhance==='function') oldEnhance();
    const root=document.getElementById('fileList'); if(!root)return;
    root.querySelectorAll('.file-card').forEach(card=>{
      const fileBtn=card.querySelector('[data-a="filemenu"]');
      if(!fileBtn)return;
      const file=(project.files||[]).find(x=>x.id===fileBtn.dataset.file); if(!file)return;
      const head=card.querySelector('.file-head');
      if(head){
        let quick=head.querySelector('.v54-layer-quick.file');
        if(!quick){quick=document.createElement('div');quick.className='v54-layer-quick file';const actions=head.querySelector('.file-actions');if(actions)head.insertBefore(quick,actions);else head.appendChild(quick);}
        const visible=file.visible!==false;
        quick.innerHTML=`<button class="v54-icon-btn v61-layer-btn v61-vis ${visible?'':'v61-off'}" data-v54-file-vis="${file.id}" title="${visible?'Hide layer':'Show layer'}">${controlIcon('eye')}</button><button class="v54-icon-btn v61-layer-btn v61-lock ${file.locked?'v61-locked':'v61-unlocked'}" data-v54-file-lock="${file.id}" title="${file.locked?'Unlock layer':'Lock layer'}">${controlIcon('lock')}</button>`;
      }
      card.querySelectorAll('.feature-row').forEach(row=>{
        const featBtn=row.querySelector('[data-a="featmenu"]'); if(!featBtn)return;
        const fid=featBtn.dataset.f; const rr=ref(fid); if(!rr)return; const f=rr.feature;
        let badge=row.querySelector('.v54-badge-slot');
        if(!badge){badge=document.createElement('div');badge.className='v54-badge-slot';const main=row.querySelector('.feature-main');if(main)row.insertBefore(badge,main);else row.prepend(badge);}
        badge.innerHTML=v54FeatureBadge(f);
        let quick=row.querySelector('.v54-layer-quick.feature');
        if(!quick){quick=document.createElement('div');quick.className='v54-layer-quick feature';const actions=row.querySelector('.feature-actions');if(actions)row.insertBefore(quick,actions);else row.appendChild(quick);}
        const picked=(project.mergeIds||[]).includes(f.id);
        const visible=f.visible!==false && file.visible!==false;
        const locked=!!(f.locked||file.locked);
        quick.innerHTML=`<button class="v54-icon-btn v61-layer-btn v61-pick ${picked?'v61-picked':''}" data-v54-feature-pick="${f.id}" title="${picked?'Unpick feature':'Pick for bulk actions'}">${controlIcon('check')}</button><button class="v54-icon-btn v61-layer-btn v61-vis ${visible?'':'v61-off'}" data-v54-feature-vis="${f.id}" title="${visible?'Hide feature':'Show feature'}">${controlIcon('eye')}</button><button class="v54-icon-btn v61-layer-btn v61-lock ${locked?'v61-locked':'v61-unlocked'}" data-v54-feature-lock="${f.id}" title="${locked?'Unlock feature':'Lock feature'}">${controlIcon('lock')}</button>`;
      });
    });
    if(typeof v54WireQuickLayerButtons==='function')v54WireQuickLayerButtons(root);
    v61EnhanceSpecialLayerIcons();
  };
  function replaceThumb(el,html,cls,title){
    if(!el)return;
    if(el.tagName&&el.tagName.toLowerCase()==='img'){
      const d=document.createElement('div');
      d.className='layer-thumb v61-object-icon '+(cls||'');
      d.title=title||'';
      d.innerHTML=html;
      el.replaceWith(d);
    }else{
      el.className='layer-thumb v61-object-icon '+(cls||'');
      el.title=title||'';
      el.innerHTML=html;
    }
  }
  window.v61EnhanceSpecialLayerIcons=function(){
    const root=document.getElementById('fileList'); if(!root)return;
    root.querySelectorAll('.file-card .file-head .layer-thumb').forEach(thumb=>{
      const text=(thumb.textContent||'').trim();
      if(text==='IMG')replaceThumb(thumb,iconSvg('image'),'image file','Image overlays');
      else if(text==='M')replaceThumb(thumb,iconSvg('ruler'),'measure file','Measurements');
      else if(text==='T')replaceThumb(thumb,'T','text file','Annotations');
    });
    root.querySelectorAll('[data-measure-row]').forEach(row=>{
      const item=(MEASURE.items||[]).find(x=>x.id===row.dataset.measureRow);
      const family=item?measureToolFamily(item.type):'';
      const type=item?.type||'';
      if(family==='annotation')replaceThumb(row.querySelector('.layer-thumb'),type==='annotationPoint'?iconSvg('point'):'T','text','Annotation');
      else replaceThumb(row.querySelector('.layer-thumb'),type==='area'?iconSvg('area'):iconSvg('ruler'),'measure','Measurement');
    });
  };
  const oldRenderSidebar=window.renderSidebar;
  if(typeof oldRenderSidebar==='function'){
    window.renderSidebar=renderSidebar=function(){
      const out=oldRenderSidebar.apply(this,arguments);
      try{v61EnhanceSpecialLayerIcons();}catch(_){ }
      return out;
    };
  }
  document.addEventListener('DOMContentLoaded',()=>{try{if(typeof renderSidebar==='function')renderSidebar();}catch(_){ }});
})();
;

/* ---- v62LayerIconRenderFixScript ---- */
// v62: post-render layer icon fixer. Does not depend on internal app closures.
(function(){
  const NS='http://www.w3.org/2000/svg';
  const svg={
    polygon:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8 L12 4 L19 9 L17 18 L8 19 Z"></path></svg>',
    multipolygon:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 9 L11 5 L17 8 L15 15 L8 16 Z"></path><path d="M9 11 L15 8 L20 12 L18 19 L11 20 Z"></path></svg>',
    line:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 17 L9 9 L15 13 L20 6"></path><circle class="fill" cx="4" cy="17" r="1.6"></circle><circle class="fill" cx="20" cy="6" r="1.6"></circle></svg>',
    point:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4.5"></circle><path d="M12 3 V6 M12 18 V21 M3 12 H6 M18 12 H21"></path></svg>',
    issue:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4 L21 20 H3 Z"></path><path d="M12 9 V14"></path><path d="M12 17 H12.1"></path></svg>',
    image:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5" width="16" height="14" rx="1"></rect><path d="M7 16 L10.2 12.8 L12.6 15.2 L15.8 12 L20 16"></path><circle cx="9" cy="9" r="1.2"></circle></svg>',
    ruler:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 17 L17 5 L20 8 L8 20 Z"></path><path d="M10 16 L8 14 M13 13 L11 11 M16 10 L14 8"></path></svg>',
    area:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 7 L14 5 L19 11 L16 19 L7 17 Z"></path><path d="M8 12 H16"></path></svg>',
    check:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect class="v62-unpicked" x="5" y="5" width="14" height="14"></rect><path class="v62-picked-mark" d="M6 12 L10 16 L18 7"></path></svg>',
    eye:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3.5 12 C6 7.5 9 5.5 12 5.5 C15 5.5 18 7.5 20.5 12 C18 16.5 15 18.5 12 18.5 C9 18.5 6 16.5 3.5 12 Z"></path><circle cx="12" cy="12" r="2.5"></circle><path class="v62-eye-slash" d="M5 20 L19 4"></path></svg>',
    lock:'<svg viewBox="0 0 24 24" aria-hidden="true"><path class="v62-lock-open" d="M8 10 V8 C8 5.8 9.6 4.5 12 4.5 C13.9 4.5 15.1 5.3 15.7 6.7"></path><path class="v62-lock-closed" d="M8 10 V8 C8 5.8 9.6 4.5 12 4.5 C14.4 4.5 16 5.8 16 8 V10"></path><rect x="6" y="10" width="12" height="10"></rect><path d="M12 14 V16"></path></svg>'
  };
  function setIcon(el,html,label){
    if(!el)return;
    if(el.dataset.v62Icon!==label){el.innerHTML=html;el.dataset.v62Icon=label;}
    if(label)el.setAttribute('aria-label',label);
  }
  function badgeKind(b){
    const cls=b.className||'';
    const txt=(b.textContent||'').trim().toUpperCase();
    if(cls.includes('invalid')||txt.includes('ISSUE'))return ['issue','Geometry issue'];
    if(cls.includes('multi')||txt.includes('MPOLY')||txt.includes('MULTI'))return ['multipolygon','MultiPolygon'];
    if(cls.includes('line')||txt.includes('LINE'))return ['line','Line'];
    if(cls.includes('point')||txt.includes('POINT'))return ['point','Point'];
    return ['polygon','Polygon'];
  }
  function enhanceSpecialThumbs(root){
    root.querySelectorAll('.measure-layer-card > .file-head .layer-thumb').forEach(t=>{t.classList.add('v61-object-icon','measure');setIcon(t,svg.ruler,'Measurements');});
    root.querySelectorAll('.annotation-layer-card > .file-head .layer-thumb').forEach(t=>{t.classList.add('v61-object-icon','text');setIcon(t,'T','Annotations');});
    root.querySelectorAll('[data-measure-row] .layer-thumb').forEach(t=>{
      const row=t.closest('[data-measure-row]');
      const name=(row?.textContent||'').toLowerCase();
      t.classList.add('v61-object-icon');
      if(name.includes('area')){t.classList.add('measure');setIcon(t,svg.area,'Area measurement');}
      else if(name.includes('annotation')||name.includes('text')){t.classList.add('text');setIcon(t,'T','Annotation');}
      else {t.classList.add('measure');setIcon(t,svg.ruler,'Measurement');}
    });
  }
  let pending=false;
  function apply(){
    pending=false;
    const root=document.getElementById('fileList'); if(!root)return;
    root.querySelectorAll('.v54-geom-badge').forEach(b=>{const [kind,label]=badgeKind(b);setIcon(b,svg[kind],label);});
    root.querySelectorAll('button.v55-pick,button.v61-pick').forEach(b=>{b.classList.add('v62-icon-control');b.classList.toggle('v62-picked',b.classList.contains('warn')||b.classList.contains('v61-picked'));setIcon(b,svg.check,b.classList.contains('v62-picked')?'Unpick feature':'Pick feature');});
    root.querySelectorAll('button.v55-vis,button.v61-vis').forEach(b=>{b.classList.add('v62-icon-control');b.classList.toggle('v62-off',b.classList.contains('off')||b.classList.contains('v61-off'));setIcon(b,svg.eye,b.classList.contains('v62-off')?'Show':'Hide');});
    root.querySelectorAll('button.v55-lock,button.v61-lock').forEach(b=>{b.classList.add('v62-icon-control');const locked=b.classList.contains('danger')||b.classList.contains('v61-locked');b.classList.toggle('v62-locked',locked);setIcon(b,svg.lock,locked?'Unlock':'Lock');});
    enhanceSpecialThumbs(root);
  }
  function schedule(){if(!pending){pending=true;requestAnimationFrame(apply);}}
  document.addEventListener('DOMContentLoaded',()=>{
    apply();
    const root=document.getElementById('fileList')||document.body;
    new MutationObserver(schedule).observe(root,{childList:true,subtree:true,attributes:true,attributeFilter:['class','style']});
    setTimeout(apply,100);setTimeout(apply,500);setTimeout(apply,1500);
  });
})();
;

