  $('circleApply').onclick=()=>{try{const next=normaliseParametricCircle({...c,center:[Number($('circleLng').value),Number($('circleLat').value)],radiusMetres:Number($('circleRadius').value),fallbackSegments:Number($('circleSegments').value)});pushHistory([f.id]);f.parametricGeometry=next;invalidateParametricGeometryCache(f);renderAll();refreshCircleEditHandles();setDirty(true);setStatus('True circle updated.');}catch(e){alert(e.message);}};
