const v140BaseRestoreAutosavePayload=restoreAutosavePayload;
restoreAutosavePayload=function(payload){const gis=gisClone(payload?.data?.gisWorkspace||gisDefaultState());const refs=gisClone(payload?.data?.referenceOverlays||[]);const result=v140BaseRestoreAutosavePayload.apply(this,arguments);gisRestoreRefs(refs);project.gisWorkspace=gisCore()?.normaliseState(gis)||gis;renderAll();syncGisRuntime();applyGisWorkspaceMode(project.gisWorkspace.workspace,{persist:true,dirty:false});gisNotify();return result;};
window.restoreAutosavePayload=restoreAutosavePayload;
const v140BaseRestoreJournalPayload=restoreJournalPayload;
restoreJournalPayload=function(payload){const gis=gisClone(payload?.checkpoint?.gisWorkspace||gisDefaultState());const refs=gisClone(payload?.checkpoint?.referenceOverlays||[]);const result=v140BaseRestoreJournalPayload.apply(this,arguments);gisRestoreRefs(refs);project.gisWorkspace=gisCore()?.normaliseState(gis)||gis;renderAll();syncGisRuntime();applyGisWorkspaceMode(project.gisWorkspace.workspace,{persist:true,dirty:false});gisNotify();return result;};
window.restoreJournalPayload=restoreJournalPayload;
writeAutosaveNow=async function(reason='autosave'){
  if(AUTOSAVE.disabled)return;
  try{
    const db=await openAutosaveDb();
    const snapshot=compactProjectState();
    const payload={
      key:AUTOSAVE.key,
      savedAt:new Date().toISOString(),
      reason,
      app:'Polygon Editor Tool',
      data:{
        files:project.files,
        polygonMoveBehavior:project.polygonMoveBehavior||'screen',
        selectedFileId:project.selectedFileId,
        selectedFeatureId:project.selectedFeatureId,
        mergeIds:project.mergeIds,
        measurements:MEASURE.items,
        imageOverlays:IMAGE.overlays,
        referenceOverlays:gisSerializeRefs(),
        gisWorkspace:gisClone(gisState()),
        dirty:project.dirty,
        ...snapshot
      }
    };
    await new Promise((resolve,reject)=>{const tx=db.transaction(AUTOSAVE.storeName,'readwrite');tx.objectStore(AUTOSAVE.storeName).put(payload);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});
    AUTOSAVE.lastSavedAt=payload.savedAt;
  }catch(err){console.warn('Autosave failed:',err);}
};
window.writeAutosaveNow=writeAutosaveNow;

