      version:GEOMETRY_HEALTH_VERSION,id:file.id,name:file.name,scope,crs:file.gisCrs||'EPSG:4326',sourceCrs:file.gisSourceCrs||file.gisCrs||'EPSG:4326',exportCrs:file.gisExportCrs||file.gisCrs||'EPSG:4326',
